            { "Research Advanced Power before building oil industry machines.", "원유 산업 설비를 건설하려면 고급 전력을 연구하세요." },
            { "Research Advanced Power so the colony can build an Oil Well.", "콜로니가 유정을 지을 수 있도록 고급 전력을 연구하세요." },
            { "Research Air Systems so the colony can desalinate salt water.", "콜로니가 염수를 담수화할 수 있도록 공기 시스템을 연구하세요." },
            { "Explore asteroid pockets to uncover salt water for desalination.", "소행성 포켓을 탐사해 담수화용 염수를 발견하세요." },
            { "Build and wire a Desalinator near salt water or pump salt water into storage.", "염수 근처에 담수화기를 짓고 전선을 연결하거나 염수를 저장소로 퍼 올리세요." },
            { "Pump salt water or place the Desalinator beside an exposed salt water pocket.", "염수를 퍼 올리거나 노출된 염수 포켓 옆에 담수화기를 배치하세요." },
            { "Keep the Desalinator powered with free dry storage for salt.", "담수화기에 전력을 공급하고 소금을 담을 건조 저장 공간을 비워 두세요." },
            { "Let the Desalinator turn salt water into clean water and salt.", "담수화기가 염수를 깨끗한 물과 소금으로 바꾸게 하세요." },
            { "Research Food Preparation before synthesizing fertilizer.", "비료를 합성하기 전에 음식 준비를 연구하세요." },
            { "Build and wire a Fertilizer Synthesizer near polluted water storage or pipes.", "오염수 저장소나 배관 근처에 비료 합성기를 짓고 전선을 연결하세요." },
            { "Store polluted water or pipe it beside the Fertilizer Synthesizer.", "오염수를 저장하거나 비료 합성기 옆으로 배관하세요." },
            { "Mine dirt so the Fertilizer Synthesizer can bind polluted water into fertilizer.", "비료 합성기가 오염수를 비료로 결합할 수 있도록 흙을 채굴하세요." },
            { "Keep the Fertilizer Synthesizer powered with free dry storage.", "비료 합성기에 전력을 공급하고 건조 저장 공간을 비워 두세요." },
            { "Let a Farm Station use synthesized fertilizer on a crop.", "농업 스테이션이 합성 비료를 작물에 사용하게 하세요." },
            { "Let the Fertilizer Synthesizer complete the fertilizer production loop.", "비료 합성기가 비료 생산 루프를 완료하게 하세요." },
            { "Explore the lower asteroid and expose a crude oil pocket for an Oil Well.", "소행성 하층을 탐사하고 유정용 원유 포켓을 노출하세요." },
            { "Build and wire an Oil Well near an exposed crude oil reservoir.", "노출된 원유 저장층 근처에 유정을 짓고 전선을 연결하세요." },
            { "Expose crude oil within 4 tiles of the Oil Well reservoir intake.", "유정 저장층 흡입구 4칸 안에 원유를 노출하세요." },
            { "Store clean water or pipe water to the Oil Well.", "깨끗한 물을 저장하거나 유정으로 물 배관을 연결하세요." },
            { "Keep the Oil Well powered and automation green while it injects water.", "유정이 물을 주입하는 동안 전력과 초록 자동화 신호를 유지하세요." },
            { "Let the Oil Well convert clean water into crude oil and natural gas.", "유정이 깨끗한 물을 원유와 천연가스로 전환하게 하세요." },
            { "Launches petroleum-and-plastic orbital missions for research data and refined metal.", "석유와 플라스틱을 실은 궤도 임무를 발사해 연구 데이터와 정제 금속을 회수합니다." },
            { "Launches petroleum-and-plastic orbital missions for research data, artifact fragments, and refined metal.", "석유와 플라스틱을 실은 궤도 임무를 발사해 연구 데이터, 유물 조각, 정제 금속을 회수합니다." },
            { "Launches petroleum-and-plastic orbital missions for research data, artifact fragments, refined metal, and post-survey niobium.", "석유와 플라스틱을 실은 궤도 임무를 발사해 연구 데이터, 유물 조각, 정제 금속, 심우주 조사 이후 니오븀을 회수합니다." },
            { "Launches petroleum-and-plastic orbital missions for research data, artifact fragments, refined metal, post-survey niobium, and thermium-era fullerene.", "석유와 플라스틱을 실은 궤도 임무를 발사해 연구 데이터, 유물 조각, 정제 금속, 심우주 조사 이후 니오븀, 테르밈 시대 풀러렌을 회수합니다." },
            { "Launches petroleum-and-plastic orbital missions; cryogenic propellant enables long-range missions after super coolant loops.", "석유와 플라스틱을 실은 궤도 임무를 발사합니다. 초냉매 루프 이후에는 극저온 추진제로 장거리 임무를 수행합니다." },
            { "Rocket mission returned orbital data and refined metal.", "로켓 임무가 궤도 데이터와 정제 금속을 회수했습니다." },
            { "Rocket mission returned orbital data, artifact fragments, and refined metal.", "로켓 임무가 궤도 데이터, 유물 조각, 정제 금속을 회수했습니다." },
            { "Rocket mission returned orbital data, artifact fragments, refined metal, and niobium.", "로켓 임무가 궤도 데이터, 유물 조각, 정제 금속, 니오븀을 회수했습니다." },
            { "Rocket mission returned orbital data, artifact fragments, refined metal, niobium, and fullerene.", "로켓 임무가 궤도 데이터, 유물 조각, 정제 금속, 니오븀, 풀러렌을 회수했습니다." },
            { "Rocket mission returned orbital data, artifact fragments, refined metal, and fullerene.", "로켓 임무가 궤도 데이터, 유물 조각, 정제 금속, 풀러렌을 회수했습니다." },
            { "Cryogenic rocket mission returned long-range data, artifact fragments, refined metal, niobium, and fullerene.", "극저온 로켓 임무가 장거리 데이터, 유물 조각, 정제 금속, 니오븀, 풀러렌을 회수했습니다." },
            { "Cryogenic rocket mission returned long-range data, artifact fragments, and refined metal.", "극저온 로켓 임무가 장거리 데이터, 유물 조각, 정제 금속을 회수했습니다." },
            { "Cryogenic rocket mission returned long-range data, artifact fragments, temporal coordinates, refined metal, niobium, and fullerene.", "극저온 로켓 임무가 장거리 데이터, 유물 조각, 시간 좌표, 정제 금속, 니오븀, 풀러렌을 회수했습니다." },
            { "Cryogenic rocket mission returned long-range data, artifact fragments, temporal coordinates, and refined metal.", "극저온 로켓 임무가 장거리 데이터, 유물 조각, 시간 좌표, 정제 금속을 회수했습니다." },
            { "Recovered niobium ", "회수한 니오븀 " },
