            { "Research Space Systems before building a Rocket Platform.", "로켓 플랫폼을 건설하려면 우주 시스템을 연구하세요." },
            { "Research Space Systems before building an Orbital Data Bank.", "궤도 데이터 뱅크를 건설하려면 우주 시스템을 연구하세요." },
            { "Research Space Systems so the colony can launch orbital missions.", "콜로니가 궤도 임무를 발사할 수 있도록 우주 시스템을 연구하세요." },
            { "Research Space Systems so the colony can analyze orbital data.", "콜로니가 궤도 데이터를 분석할 수 있도록 우주 시스템을 연구하세요." },
            { "Research Automation Logistics so the colony can analyze natural vent cycles.", "콜로니가 자연 분출구 주기를 분석할 수 있도록 자동화 물류를 연구하세요." },
            { "Build and wire a Rocket Platform under open sky.", "열린 하늘 아래에 로켓 플랫폼을 짓고 전선을 연결하세요." },
            { "Build and wire an Orbital Data Bank to analyze returned mission data.", "회수한 임무 데이터를 분석할 궤도 데이터 뱅크를 짓고 전선을 연결하세요." },
            { "Build and wire a Vent Analyzer within range of a natural vent.", "자연 분출구 범위 안에 분출구 분석기를 짓고 전선을 연결하세요." },
            { "Move or add a Vent Analyzer within range of each unanalyzed natural vent.", "아직 분석되지 않은 각 자연 분출구 범위 안으로 분출구 분석기를 옮기거나 추가하세요." },
            { "Clear the sky above the Rocket Platform before launch prep can continue.", "발사 준비가 계속되도록 로켓 플랫폼 위의 하늘을 비우세요." },
            { "Refine crude oil into petroleum so the Rocket Platform has fuel.", "로켓 플랫폼 연료를 위해 원유를 석유로 정제하세요." },
            { "Press petroleum into plastic so the Rocket Platform can load mission parts.", "로켓 플랫폼이 임무 부품을 적재할 수 있도록 석유를 플라스틱으로 압착하세요." },
            { "Keep the Rocket Platform powered while it prepares an orbital mission.", "궤도 임무를 준비하는 동안 로켓 플랫폼에 전력을 공급하세요." },
            { "Let the Rocket Platform consume petroleum and plastic until one orbital mission returns.", "로켓 플랫폼이 석유와 플라스틱을 소비해 궤도 임무 하나를 완료하게 하세요." },
            { "Launch blocked: research Space Systems.", "발사 막힘: 우주 시스템을 연구하세요." },
            { "Launch blocked: Rocket Platform missing.", "발사 막힘: 로켓 플랫폼이 없습니다." },
            { "Launch blocked: Rocket Platform needs repair.", "발사 막힘: 로켓 플랫폼 수리가 필요합니다." },
            { "Launch blocked: Rocket Platform is submerged.", "발사 막힘: 로켓 플랫폼이 침수되었습니다." },
            { "Launch blocked: clear vertical sky above the Rocket Platform.", "발사 막힘: 로켓 플랫폼 위 수직 하늘을 비우세요." },
            { "Launch blocked: needs adjacent or under-floor power wire.", "발사 막힘: 인접 또는 바닥 아래 전선이 필요합니다." },
            { "Launch blocked: power circuit has no stored power.", "발사 막힘: 전력 회로에 저장 전력이 없습니다." },
            { "Launch blocked: automation signal is red.", "발사 막힘: 자동화 신호가 빨간색입니다." },
            { "Launch blocked: refine crude oil into petroleum.", "발사 막힘: 원유를 석유로 정제하세요." },
            { "Launch blocked: press petroleum into plastic.", "발사 막힘: 석유를 플라스틱으로 압착하세요." },
            { "Launch ready: next mission will be cryogenic long-range.", "발사 준비됨: 다음 임무는 극저온 장거리 임무입니다." },
            { "Launch prep ready: loading cryogenic propellant for long-range mission.", "발사 준비 진행 가능: 장거리 임무용 극저온 추진제를 적재 중입니다." },
            { "Launch prep ready: no cryogenic propellant, regular orbital mission will continue.", "발사 준비 진행 가능: 극저온 추진제가 없어 일반 궤도 임무가 계속됩니다." },
            { "Launch prep ready: regular orbital mission can advance.", "발사 준비 진행 가능: 일반 궤도 임무가 진행됩니다." },
            { "Launch another orbital mission so the Orbital Data Bank has data to analyze.", "궤도 데이터 뱅크가 분석할 데이터를 갖도록 궤도 임무를 하나 더 발사하세요." },
            { "Connect the Orbital Data Bank to powered wire and keep automation green.", "궤도 데이터 뱅크를 전력이 있는 전선에 연결하고 자동화 신호를 초록으로 유지하세요." },
            { "Let the Orbital Data Bank analyze mission data into research points.", "궤도 데이터 뱅크가 임무 데이터를 연구점수로 분석하게 하세요." },
            { "Launch repeated orbital missions to complete a deep space survey.", "심우주 조사를 완료하도록 궤도 임무를 반복 발사하세요." },
            { "Analyze enough orbital data to chart a stable deep space route.", "안정적인 심우주 항로를 그릴 만큼 충분한 궤도 데이터를 분석하세요." },
            { "Launch another orbital mission so the deep space survey has data to analyze.", "심우주 조사가 분석할 데이터를 확보하도록 궤도 임무를 하나 더 발사하세요." },
            { "Launch another orbital mission to recover a space artifact fragment.", "우주 유물 조각을 회수하도록 궤도 임무를 하나 더 발사하세요." },
            { "Launch another orbital mission so the Orbital Data Bank can analyze recovered artifacts.", "궤도 데이터 뱅크가 회수한 유물을 분석할 수 있도록 궤도 임무를 하나 더 발사하세요." },
            { "Keep the Orbital Data Bank powered while it analyzes recovered space artifacts.", "회수한 우주 유물을 분석하는 동안 궤도 데이터 뱅크에 전력을 유지하세요." },
            { "Let the Orbital Data Bank analyze recovered space artifacts for research and decor.", "궤도 데이터 뱅크가 회수한 우주 유물을 연구와 장식 보너스로 분석하게 하세요." },
            { "Analysis blocked: research Space Systems.", "분석 막힘: 우주 시스템을 연구하세요." },
            { "Analysis blocked: Orbital Data Bank missing.", "분석 막힘: 궤도 데이터 뱅크가 없습니다." },
            { "Analysis blocked: Orbital Data Bank needs repair.", "분석 막힘: 궤도 데이터 뱅크 수리가 필요합니다." },
            { "Analysis blocked: Orbital Data Bank is submerged.", "분석 막힘: 궤도 데이터 뱅크가 침수되었습니다." },
            { "Analysis blocked: needs adjacent or under-floor power wire.", "분석 막힘: 인접 또는 바닥 아래 전선이 필요합니다." },
            { "Analysis blocked: power circuit has no stored power.", "분석 막힘: 전력 회로에 저장 전력이 없습니다." },
            { "Analysis blocked: automation signal is red.", "분석 막힘: 자동화 신호가 빨간색입니다." },
            { "Analysis ready: charting temporal route from mission data.", "분석 준비됨: 임무 데이터로 시간 균열 항로를 작성합니다." },
            { "Analysis ready: mission data and artifact fragments.", "분석 준비됨: 임무 데이터와 유물 조각." },
            { "Analysis ready: mission data.", "분석 준비됨: 임무 데이터." },
            { "Analysis ready: radiation samples.", "분석 준비됨: 방사선 샘플." },
            { "Signal ready: stabilizing temporal tear.", "신호 준비됨: 시간 균열을 안정화합니다." },
            { "Analysis blocked: recovered artifacts need fresh orbital data.", "분석 막힘: 회수한 유물에는 새 궤도 데이터가 필요합니다." },
            { "Analysis idle: launch a Rocket Platform mission for orbital data.", "분석 대기: 궤도 데이터를 위해 로켓 플랫폼 임무를 발사하세요." },
            { "Research Space Systems before starting radiation sample analysis.", "방사선 샘플 분석을 시작하기 전에 우주 시스템을 연구하세요." },
            { "Route lead-suited duplicants through radiation zones to collect research samples.", "연구 샘플을 수집하도록 납 보호복을 입은 복제체를 방사선 구역으로 보내세요." },
            { "Build and wire an Orbital Data Bank to analyze collected radiation samples.", "수집한 방사선 샘플을 분석하도록 궤도 데이터 뱅크를 짓고 전선을 연결하세요." },
            { "Keep the Orbital Data Bank powered while it analyzes radiation samples.", "방사선 샘플을 분석하는 동안 궤도 데이터 뱅크에 전력을 유지하세요." },
            { "Let the Orbital Data Bank finish queued orbital data before radiation sample analysis.", "방사선 샘플 분석 전에 궤도 데이터 뱅크가 대기 중인 궤도 데이터를 먼저 처리하게 하세요." },
            { "Let the Orbital Data Bank analyze radiation samples into nuclear research.", "궤도 데이터 뱅크가 방사선 샘플을 핵 연구로 분석하게 하세요." },
            { "Keep the space program powered until the deep space survey is recorded.", "심우주 조사가 기록될 때까지 우주 프로그램에 전력을 유지하세요." },
            { "Complete the deep space survey before recovering niobium.", "니오븀을 회수하기 전에 심우주 조사를 완료하세요." },
            { "Build a Rocket Platform so deep space missions can recover niobium.", "심우주 임무가 니오븀을 회수할 수 있도록 로켓 플랫폼을 지으세요." },
            { "Launch a post-survey rocket mission to recover niobium ore.", "조사 완료 후 로켓 임무를 발사해 니오븀 원석을 회수하세요." },
            { "Build and wire a Metal Refinery to alloy thermium.", "테르밈을 합금할 금속 정제기를 짓고 전선을 연결하세요." },
            { "Produce extra steel so thermium alloying does not drain bunker reserves.", "테르밈 합금이 벙커 보강 예비분을 소모하지 않도록 강철을 추가 생산하세요." },
            { "Launch another deep space mission to recover more niobium.", "니오븀을 더 회수하도록 심우주 임무를 하나 더 발사하세요." },
            { "Store clean water or pipe it beside the Metal Refinery as thermium coolant.", "테르밈 냉각수로 쓸 깨끗한 물을 저장하거나 금속 정제기 옆으로 배관하세요." },
            { "Free dry storage space so the Metal Refinery can store thermium.", "금속 정제기가 테르밈을 저장할 수 있도록 건식 저장 공간을 비우세요." },
            { "Keep the Metal Refinery powered and automation green while thermium alloying runs.", "테르밈 합금이 진행되는 동안 금속 정제기에 전력과 초록 자동화 신호를 유지하세요." },
            { "Let the Metal Refinery alloy thermium before hot machinery is coated.", "고열 장비가 코팅되기 전에 금속 정제기가 테르밈을 합금하게 두세요." },
            { "Let stored thermium coat hot industrial machines for extreme overheat resistance.", "저장된 테르밈으로 고열 산업 장비를 코팅해 극한 과열 저항을 확보하세요." },
            { "Finish thermium machinery before recovering fullerene.", "풀러렌을 회수하기 전에 테르밈 장비를 완성하세요." },
            { "Build a Rocket Platform so deep space missions can recover fullerene.", "심우주 임무가 풀러렌을 회수할 수 있도록 로켓 플랫폼을 지으세요." },
            { "Launch a thermium-era rocket mission to recover fullerene.", "테르밈 시대 로켓 임무를 발사해 풀러렌을 회수하세요." },
            { "Build and wire a Metal Refinery to synthesize super coolant.", "초냉매를 합성할 금속 정제기를 짓고 전선을 연결하세요." },
            { "Keep a thermium reserve so super coolant synthesis can run.", "초냉매 합성이 진행되도록 테르밈 예비분을 유지하세요." },
            { "Refine crude oil into petroleum for super coolant synthesis.", "초냉매 합성에 쓸 석유를 위해 원유를 정제하세요." },
            { "Feed clean water to the Metal Refinery for super coolant synthesis.", "초냉매 합성을 위해 금속 정제기에 깨끗한 물을 공급하세요." },
            { "Free dry storage space so synthesized super coolant can be stored.", "합성된 초냉매를 보관할 수 있도록 건식 저장 공간을 비우세요." },
            { "Keep the Metal Refinery powered while it synthesizes super coolant.", "초냉매를 합성하는 동안 금속 정제기에 전력을 유지하세요." },
            { "Build a Thermo Aquatuner so super coolant can stabilize the loop.", "초냉매가 루프를 안정화할 수 있도록 액체 냉각기를 지으세요." },
            { "Run liquid through a Thermo Aquatuner while super coolant is available.", "초냉매가 있을 때 액체를 액체 냉각기에 통과시키세요." },
            { "Stabilize coolant pipes before proving the super coolant loop.", "초냉매 루프를 증명하기 전에 냉각수 배관을 안정화하세요." },
            { "Keep the Thermo Aquatuner running on super coolant until the advanced cooling loop is proven.", "고급 냉각 루프가 검증될 때까지 액체 냉각기가 초냉매를 쓰며 계속 작동하게 하세요." },
            { "Prove the super coolant loop before producing cryogenic rocket propellant.", "극저온 로켓 추진제를 생산하기 전에 초냉매 루프를 검증하세요." },
            { "Build and wire a Thermo Regulator to chill piped oxygen and hydrogen into cryogenic propellant.", "배관 산소와 수소를 극저온 추진제로 냉각할 열 조절기를 짓고 전선을 연결하세요." },
            { "Pipe oxygen to the Thermo Regulator for cryogenic propellant.", "극저온 추진제를 위해 열 조절기로 산소를 배관하세요." },
            { "Pipe hydrogen to the Thermo Regulator for cryogenic propellant.", "극저온 추진제를 위해 열 조절기로 수소를 배관하세요." },
            { "Keep super coolant available so the Thermo Regulator can condense cryogenic propellant.", "열 조절기가 극저온 추진제를 응축할 수 있도록 초냉매를 유지하세요." },
            { "Free dry storage space so cryogenic propellant can be stored.", "극저온 추진제를 저장할 수 있도록 건식 저장 공간을 비우세요." },
            { "Keep the Thermo Regulator powered while it condenses cryogenic propellant.", "극저온 추진제를 응축하는 동안 열 조절기에 전력을 유지하세요." },
            { "Build a Rocket Platform so cryogenic propellant can launch long-range missions.", "극저온 추진제로 장거리 임무를 발사할 로켓 플랫폼을 지으세요." },
            { "Clear the sky above the Rocket Platform before a cryogenic mission can launch.", "극저온 임무가 발사될 수 있도록 로켓 플랫폼 위의 하늘을 비우세요." },
            { "Produce enough cryogenic propellant for one long-range rocket mission.", "장거리 로켓 임무 하나에 충분한 극저온 추진제를 생산하세요." },
            { "Refine petroleum so the Rocket Platform can finish cryogenic launch prep.", "로켓 플랫폼이 극저온 발사 준비를 끝낼 수 있도록 석유를 정제하세요." },
            { "Press plastic so the Rocket Platform can finish cryogenic launch prep.", "로켓 플랫폼이 극저온 발사 준비를 끝낼 수 있도록 플라스틱을 압착하세요." },
            { "Keep the Rocket Platform powered while it loads cryogenic propellant.", "극저온 추진제를 적재하는 동안 로켓 플랫폼에 전력을 유지하세요." },
            { "Launch a long-range cryogenic rocket mission using stored propellant.", "저장된 추진제를 사용해 장거리 극저온 로켓 임무를 발사하세요." },
            { "Complete cryogenic rocket operations before charting the temporal tear.", "시간 균열 항로를 작성하기 전에 극저온 로켓 운영을 완료하세요." },
            { "Launch another cryogenic long-range mission to recover temporal coordinate fragments.", "시간 균열 좌표 조각을 회수하도록 장거리 극저온 임무를 하나 더 발사하세요." },
            { "Launch cryogenic missions until enough temporal coordinate fragments are recovered.", "충분한 시간 균열 좌표 조각을 회수할 때까지 극저온 임무를 발사하세요." },
            { "Build and wire an Orbital Data Bank to analyze temporal coordinate fragments.", "시간 균열 좌표 조각을 분석할 궤도 데이터 뱅크를 짓고 전선을 연결하세요." },
            { "Launch another cryogenic mission so the Orbital Data Bank has long-range data for the temporal tear.", "궤도 데이터 뱅크가 시간 균열용 장거리 데이터를 갖도록 극저온 임무를 하나 더 발사하세요." },
            { "Keep the Orbital Data Bank powered while it charts the temporal tear route.", "시간 균열 항로를 작성하는 동안 궤도 데이터 뱅크에 전력을 유지하세요." },
            { "Let the Orbital Data Bank analyze long-range mission data into temporal coordinates.", "궤도 데이터 뱅크가 장거리 임무 데이터를 시간 좌표로 분석하게 하세요." },
            { "Let the Orbital Data Bank decode recovered temporal coordinate fragments.", "궤도 데이터 뱅크가 회수한 시간 좌표 조각을 해독하게 하세요." },
            { "Keep a Space Scanner under open sky so the temporal tear signal has a surface lock.", "시간 균열 신호가 지표 고정을 얻도록 열린 하늘 아래 우주 스캐너를 유지하세요." },
            { "Reserve super coolant so the temporal tear signal stays thermally stable.", "시간 균열 신호가 열적으로 안정되도록 초냉매 예비분을 남겨두세요." },
            { "Temporal route blocked: launch more cryogenic long-range missions.", "시간 균열 항로 막힘: 극저온 장거리 임무를 더 발사하세요." },
            { "Temporal route blocked: recover coordinate fragments with cryogenic missions.", "시간 균열 항로 막힘: 극저온 임무로 좌표 조각을 회수하세요." },
            { "Temporal route ready for data-bank analysis.", "시간 균열 항로를 데이터 뱅크에서 분석할 준비가 되었습니다." },
            { "Temporal route blocked: launch another cryogenic mission for long-range data.", "시간 균열 항로 막힘: 장거리 데이터를 위해 극저온 임무를 하나 더 발사하세요." },
            { "Temporal signal blocked: needs open-sky Space Scanner.", "시간 균열 신호 막힘: 열린 하늘의 우주 스캐너가 필요합니다." },
            { "Temporal signal blocked: reserve super coolant.", "시간 균열 신호 막힘: 초냉매 예비분을 확보하세요." },
            { "Temporal signal stabilized.", "시간 균열 신호가 안정화되었습니다." },
            { "Temporal signal ready: keep this data bank powered.", "시간 균열 신호 준비됨: 이 데이터 뱅크의 전력을 유지하세요." },
            { "Keep the Orbital Data Bank powered while it stabilizes the temporal tear signal.", "시간 균열 신호를 안정화하는 동안 궤도 데이터 뱅크에 전력을 유지하세요." },
            { "Keep the Orbital Data Bank powered with open-sky scanner support until the temporal tear signal stabilizes.", "시간 균열 신호가 안정될 때까지 열린 하늘의 스캐너 지원과 궤도 데이터 뱅크 전력을 유지하세요." },
            { "Keep the space program stable until the temporal tear signal is recorded.", "시간 균열 신호가 기록될 때까지 우주 프로그램을 안정적으로 유지하세요." },
            { "Keep the Vent Analyzer powered, green, and within range until analysis completes.", "분석이 끝날 때까지 분출구 분석기에 전력과 초록 신호를 공급하고 범위 안에 유지하세요." },
            { "Let the Vent Analyzer finish cycle analysis to unlock output forecasts.", "분출구 분석기가 주기 분석을 끝내 산출 예측을 해금하게 하세요." },
            { "Let Vent Analyzers finish cycle analysis for every discovered natural vent.", "분출구 분석기가 발견된 모든 자연 분출구의 주기 분석을 끝내게 하세요." },
            { "All discovered natural vents are dormant; build storage and pumps while waiting for the next eruption window.", "발견된 자연 분출구가 모두 휴면 중입니다. 다음 분출 구간을 기다리며 저장소와 펌프를 준비하세요." },
            { "Tap active natural vents with pumps and storage before the eruption window closes.", "분출 구간이 끝나기 전에 활성 자연 분출구를 펌프와 저장소로 활용하세요." },
            { "Keep Vent Analyzers powered and green until every discovered natural vent is analyzed.", "발견된 모든 자연 분출구가 분석될 때까지 분출구 분석기에 전력과 초록 신호를 유지하세요." },
            { "Explore the asteroid until a Steam Vent, Hydrogen Vent, Natural Gas Vent, or Metal Volcano is uncovered.", "증기 분출구, 수소 분출구, 천연가스 분출구, 금속 화산 중 하나가 드러날 때까지 소행성을 탐사하세요." },
            { "Tap a natural vent: build a Water Pump or Gas Pump near the vent pocket.", "자연 분출구를 활용하세요: 분출구 공간 근처에 물 펌프나 가스 펌프를 지으세요." },
            { "Let a natural vent produce renewable water, hydrogen, or natural gas, then route it through pipes.", "자연 분출구가 재생 가능한 물, 수소, 천연가스를 생산하게 한 뒤 배관으로 운송하세요." },
            { "Explore the lower asteroid to uncover a Metal Volcano.", "하층 소행성을 탐사해 금속 화산을 발견하세요." },
            { "Use the Vent Analyzer forecast and prepare insulated storage while the Metal Volcano is dormant.", "금속 화산이 휴면 중일 때 분출구 분석기 예보를 보고 단열 저장 구역을 준비하세요." },
            { "Build insulated tiles around the Metal Volcano before collecting hot refined metal.", "뜨거운 정제 금속을 수거하기 전에 금속 화산 주변에 단열 타일을 지으세요." },
            { "Let the analyzed Metal Volcano erupt and sweep the hot refined metal into storage.", "분석된 금속 화산이 분출하게 두고 뜨거운 정제 금속을 저장소로 청소하세요." },
            { "Collect the Metal Volcano output after insulating the chamber around the hot refined metal.", "뜨거운 정제 금속 주변 방을 단열한 뒤 금속 화산 산출물을 수거하세요." },
            { "Use the analyzed Metal Volcano forecast to build insulated storage before the next eruption.", "다음 분출 전에 분석된 금속 화산 예보를 참고해 단열 저장 구역을 지으세요." },
            { "Explore the asteroid until a Steam Vent, Water Geyser, Cool Steam Vent, Leaky Oil Fissure, Salt Water Geyser, Cool Slush Geyser, Polluted Water Vent, Chlorine Gas Vent, Carbon Dioxide Vent, Polluted Oxygen Vent, Hydrogen Vent, Natural Gas Vent, Metal Volcano, or Magma Volcano is uncovered.", "증기 분출구, 물 간헐천, 냉증기 분출구, 누출 원유 분출구, 염수 간헐천, 냉슬러시 간헐천, 오염수 분출구, 염소 가스 분출구, 이산화탄소 분출구, 오염 산소 분출구, 수소 분출구, 천연가스 분출구, 금속 화산, 마그마 화산 중 하나가 드러날 때까지 소행성을 탐사하세요." },
            { "Let a natural vent produce renewable water, steam, crude oil, salt water, polluted water, chlorine, carbon dioxide, polluted oxygen, hydrogen, natural gas, or hot magma, then route or harvest it with the right machinery.", "자연 분출구가 재생 가능한 물, 증기, 원유, 염수, 오염수, 염소, 이산화탄소, 오염 산소, 수소, 천연가스, 뜨거운 마그마를 생산하게 한 뒤 알맞은 설비로 운송하거나 회수하세요." },
            { "Explore the lower asteroid until a Magma Volcano is uncovered.", "하층 소행성을 탐사해 마그마 화산을 발견하세요." },
            { "Analyze the Magma Volcano so the colony can forecast its eruption cycle.", "마그마 화산을 분석해 분출 주기를 예측할 수 있게 하세요." },
            { "Research Advanced Power so Steam Turbines can tame the Magma Volcano.", "증기 터빈으로 마그마 화산을 제어할 수 있도록 고급 전력을 연구하세요." },
            { "Build and wire a Steam Turbine above a sealed Magma Volcano steam chamber.", "밀폐된 마그마 화산 증기 챔버 위에 증기 터빈을 짓고 배선하세요." },
            { "Build Insulated Tiles around the Magma Volcano chamber before letting magma pool.", "마그마가 고이기 전에 마그마 화산 챔버 주변에 단열 타일을 지으세요." },
            { "Use the Vent Analyzer forecast and stage controlled water while the Magma Volcano is dormant.", "마그마 화산이 휴면 중일 때 분출구 분석기 예보를 보고 제어용 물을 준비하세요." },
            { "Let the analyzed Magma Volcano erupt into an insulated heat chamber.", "분석된 마그마 화산이 단열 열 챔버 안으로 분출하게 두세요." },
            { "Feed controlled water near the erupted magma so steam reaches the Steam Turbine.", "분출된 마그마 근처에 제어된 물을 공급해 증기가 증기 터빈에 닿게 하세요." },
            { "Keep the Magma Volcano sealed while the Steam Turbine harvests its heat.", "증기 터빈이 열을 회수하는 동안 마그마 화산을 밀폐 상태로 유지하세요." },
            { "Powered analysis station. Converts returned orbital data into research points.", "전력 분석 설비입니다. 회수한 궤도 데이터를 연구점수로 변환합니다." },
            { "Powered analysis station. Converts returned orbital data and artifacts into research points.", "전력 분석 설비입니다. 회수한 궤도 데이터와 유물을 연구점수로 변환합니다." },
            { "Powered analysis station. Converts returned orbital data, artifacts, radiation samples, and temporal fragments into research.", "전력 분석 설비입니다. 회수한 궤도 데이터, 유물, 방사선 샘플, 시간 조각을 연구로 변환합니다." },
            { "Powered analysis station. Studies nearby natural vent active and dormant cycles.", "전력 분석 설비입니다. 근처 자연 분출구의 활성/휴면 주기를 분석합니다." },
