            { "Needs power and green automation for analysis.", "분석하려면 전력과 초록 자동화 신호가 필요합니다." },
            { "Natural vent analysis complete. Output forecast and tuning bonus active.", "자연 분출구 분석 완료. 산출 예측과 튜닝 보너스가 활성화되었습니다." },
            { "Renewable natural volcano. Erupts hot refined metal into nearby open tiles while active.", "재생 가능한 자연 화산입니다. 활성 상태일 때 주변 열린 칸에 뜨거운 정제 금속을 분출합니다." },
            { "Renewable natural volcano. Erupts magma into a nearby open heat chamber while active.", "재생 가능한 자연 화산입니다. 활성 상태일 때 주변 열린 열 챔버에 마그마를 분출합니다." },
            { "Output tile available.", "출력 칸 사용 가능." },
            { "Output chamber available.", "출력 챔버 사용 가능." },
            { "Output blocked by buildings or conduits.", "출력이 건물이나 배관에 막혔습니다." },
            { "Output blocked or full.", "출력 칸이 막혔거나 가득 찼습니다." },
            { "Volcanic refined metal generated ", "화산 정제 금속 생성량 " },
            { "Magma volcano generated ", "마그마 화산 생성량 " },
            { "Seal it in Insulated Tiles and feed controlled steam to Steam Turbines.", "단열 타일로 밀폐하고 제어된 증기를 증기 터빈에 공급하세요." },
            { "Use insulated tiles, sweepers, and storage to tame the heat.", "단열 타일, 청소기, 저장소로 열을 제어하세요." },
            { "Analysis complete: output forecast and +", "분석 완료: 산출 예측과 +" },
