            { "% tuning bonus active.", "% 튜닝 보너스 활성." },
            { "s. Build a powered Vent Analyzer nearby.", "초. 근처에 전력이 공급되는 분출구 분석기를 지으세요." },
            { "s  Bonus ", "초  보너스 " },
            { "Nearest vent ", "가장 가까운 분출구 " },
            { "No natural vent in analysis range.", "분석 범위 안에 자연 분출구가 없습니다." },
            { "Analysis complete. Output forecast and tuning bonus active.", "분석 완료. 산출 예측과 튜닝 보너스가 활성화되었습니다." },
            { "Analyzing nearby vent cycles.", "근처 분출구 주기를 분석 중입니다." },
            { "Cycle forecast locked until this natural vent is analyzed.", "이 자연 분출구가 분석될 때까지 주기 예측이 잠겨 있습니다." },
            { "Forecast: active ", "예측: 활성 " },
            { "s, dormant ", "초, 휴면 " },
            { "s, average ", "초, 평균 " },
            { "Explore the lower asteroid to uncover magma for geothermal heat.", "소행성 하층을 탐사해 지열용 마그마를 발견하세요." },
            { "Research Advanced Power so Steam Turbines can harvest geothermal heat.", "증기 터빈으로 지열을 회수할 수 있도록 고급 전력을 연구하세요." },
            { "Build and wire a Steam Turbine near magma-heated steam.", "마그마로 가열된 증기 근처에 증기 터빈을 짓고 전선을 연결하세요." },
            { "Expose insulated water or steam near magma so geothermal heat can move safely.", "마그마 근처의 물이나 증기를 단열 구역 안에서 노출해 지열이 안전하게 이동하게 하세요." },
            { "Let magma flash nearby water into steam and feed the Steam Turbine.", "마그마가 근처 물을 증기로 플래시시켜 증기 터빈에 공급하게 하세요." },
            { "Magma: extreme geothermal heat source. Do not open without insulation or steam capture.", "마그마: 극한의 지열 열원입니다. 단열이나 증기 포집 없이 열지 마세요." },
            { "Heat moved ", "이동한 열 " },
            { "  Steam flashed ", "  플래시 증기 " },
            { "Use insulated tiles, water, and Steam Turbines to harvest geothermal power.", "단열 타일, 물, 증기 터빈으로 지열 발전을 확보하세요." },
            { "Needs clear vertical sky above the platform.", "플랫폼 위 수직 하늘이 비어 있어야 합니다." },
            { "Needs plastic from a Polymer Press.", "폴리머 프레스에서 생산한 플라스틱이 필요합니다." },
            { "Ready to prepare orbital missions.", "궤도 임무 준비가 가능합니다." },
            { "Needs powered wire access.", "전력이 공급되는 전선 연결이 필요합니다." },
            { "Water Pump must be built beside a liquid tile.", "Water Pump는 액체 칸 옆에 건설해야 합니다." },
            { "Pump Liquid", "액체 펌프" },
            { "Powered plumbing sends water or polluted water into adjacent pipes.", "전원이 공급되면 물이나 오염수를 인접 배관으로 보냅니다." },
            { "Pipe connected; needs power and green automation for automatic water pumping.", "배관이 연결되었습니다. 자동 물 펌프에는 전력과 초록 자동화 신호가 필요합니다." },
            { "Pipe connected; needs power and green automation for automatic water or petroleum pumping.", "배관이 연결되었습니다. 물 또는 석유 자동 펌프에는 전력과 초록 자동화 신호가 필요합니다." },
