            { "Food policy set to SAFE: stale or contaminated meals are blocked unless starvation is critical.", "식품 정책 SAFE: 치명적 굶주림이 아니면 상했거나 오염된 식사를 막습니다." },
            { "Food policy set to ALL: duplicants may eat stale or contaminated meals.", "식품 정책 ALL: 복제체가 상했거나 오염된 식사도 먹을 수 있습니다." },
            { "Medical leave enabled: sick duplicants avoid routine errands until vitals recover.", "의료 휴직 활성화: 아픈 복제체가 상태가 회복될 때까지 일반 심부름을 피합니다." },
