            { "Water\nD6 M12", "물휴식\nD6 M12" },

            { "Colony charter complete. Expand into the asteroid and keep the colony alive.", "콜로니 헌장이 완료되었습니다. 소행성으로 확장하며 생존을 유지하세요." },
            { "Build a safe barracks: 12 floor tiles and one bed per duplicant.", "안전한 막사를 만드세요: 바닥 12칸과 복제체마다 침대 1개가 필요합니다." },
            { "Build an Outhouse so duplicants can relieve bladder pressure safely.", "복제체가 안전하게 볼일을 볼 수 있도록 재래식 화장실을 지으세요." },
            { "Build an Outhouse or Lavatory so duplicants can relieve bladder pressure safely.", "복제체가 안전하게 볼일을 볼 수 있도록 재래식 화장실이나 수세식 화장실을 지으세요." },
            { "Build a Wash Basin near the outhouse so duplicants clean germs before getting sick.", "병에 걸리기 전에 손을 씻도록 화장실 근처에 세면대를 지으세요." },
            { "Build a Wash Basin or Shower near toilets so duplicants clean germs before getting sick.", "병에 걸리기 전에 화장실 근처에 세면대나 샤워기를 지어 병균을 씻게 하세요." },
            { "Build a Wash Basin, Hand Sanitizer, or Shower near toilets so duplicants clean germs before getting sick.", "병에 걸리기 전에 화장실 근처에 세면대, 손 소독기, 샤워기를 지어 병균을 제거하세요." },
            { "Store clean water so the Wash Basin can remove germs from duplicants.", "세면대가 병균을 제거할 수 있도록 깨끗한 물을 확보하세요." },
            { "Store clean water so hygiene fixtures can remove germs from duplicants.", "위생 설비가 병균을 제거할 수 있도록 깨끗한 물을 확보하세요." },
            { "Mine or store bleach stone so the Hand Sanitizer can clean germy duplicants.", "손 소독기가 병균 묻은 복제체를 소독할 수 있도록 표백석을 채굴하거나 저장하세요." },
            { "Let a germy duplicant wash hands at the Wash Basin to prove hygiene control.", "병균에 노출된 복제체가 세면대에서 손을 씻게 하세요." },
            { "Let a germy duplicant wash hands or shower to prove hygiene control.", "병균에 노출된 복제체가 손을 씻거나 샤워해 위생 제어를 증명하게 하세요." },
            { "Let a germy duplicant wash hands, sanitize, or shower to prove hygiene control.", "병균에 노출된 복제체가 손을 씻거나 소독하거나 샤워해 위생 제어를 증명하게 하세요." },
            { "Use Disinfect on a germy tile before germs spread through the base.", "병균이 기지에 퍼지기 전에 병균 칸에 Disinfect를 지정하세요." },
            { "Dig a slime pocket to expose germs, then use Disinfect on the germy tile.", "슬라임 포켓을 파서 병균을 드러낸 뒤 병균 칸에 Disinfect를 지정하세요." },
            { "Build a Hand Sanitizer to disinfect duplicants without spending clean water.", "깨끗한 물을 쓰지 않고 복제체를 소독할 손 소독기를 지으세요." },
            { "Mine bleach stone so the Hand Sanitizer has disinfectant to consume.", "손 소독기가 사용할 소독제를 확보하도록 표백석을 채굴하세요." },
            { "Send a germy duplicant to the Hand Sanitizer to consume bleach stone and prove waterless hygiene.", "병균 묻은 복제체를 손 소독기로 보내 표백석을 소비하고 무수 위생을 증명하세요." },
            { "Use Red Alert during an emergency to push urgent errands, at the cost of stress.", "비상 상황에서 Red Alert를 사용해 스트레스를 감수하고 긴급 작업을 밀어붙이세요." },
            { "Keep Red Alert active until urgent errands have accelerated for a few seconds.", "긴급 작업이 몇 초 동안 가속될 때까지 Red Alert를 유지하세요." },
            { "Inspect an errand and mark Yellow Alert so duplicants escalate one urgent task.", "심부름을 조사하고 Yellow Alert로 지정해 복제체가 긴급 작업 하나를 우선 처리하게 하세요." },
            { "Build a Compost and process polluted dirt from outhouses or spoiled food.", "퇴비장을 지어 화장실이나 상한 음식에서 나온 오염된 흙을 처리하세요." },
            { "Compost blocked: compost station missing.", "퇴비 막힘: 퇴비장이 없습니다." },
            { "Compost blocked: compost station needs repair.", "퇴비 막힘: 퇴비장 수리가 필요합니다." },
            { "Compost blocked: compost station is submerged.", "퇴비 막힘: 퇴비장이 침수되었습니다." },
            { "Compost blocked: needs polluted dirt.", "퇴비 막힘: 오염된 흙이 필요합니다." },
            { "Compost blocked: no reachable duplicant path to station.", "퇴비 막힘: 퇴비장까지 도달 가능한 복제체 경로가 없습니다." },
            { "Compost blocked: ", "퇴비 막힘: " },
            { "Compost ready: compost errand queued. ", "퇴비 준비됨: 퇴비 심부름 대기 중. " },
            { "Compost ready: can process polluted dirt.", "퇴비 준비됨: 오염된 흙을 처리할 수 있습니다." },
            { "Build a Storage Bin so mined dirt, metal, algae, and coal have room to accumulate.", "채굴한 흙, 금속, 조류, 석탄을 보관할 저장고를 지으세요." },
            { "Use Sweep on mined debris so duplicants move resources into storage.", "채굴 잔해에 Sweep을 지정해 복제체가 자원을 저장소로 옮기게 하세요." },
            { "Dig natural tiles to create debris, then Sweep it into storage.", "자연 타일을 파서 잔해를 만들고 저장소로 Sweep하세요." },
            { "Secure water: build a water pump beside a blue water pocket.", "물을 확보하세요: 파란 물웅덩이 옆에 물 펌프를 지으세요." },
            { "Build Liquid Pipes and a Liquid Vent to move water through plumbing.", "액체 배관과 액체 배출구를 지어 물을 이동시키세요." },
            { "Start research: build a research station and complete Air Systems.", "연구를 시작하세요: 연구소를 짓고 공기 시스템을 완료하세요." },
            { "Stabilize oxygen: build and fuel an oxygen diffuser.", "산소를 안정화하세요: 산소 발생기를 짓고 조류를 공급하세요." },
            { "Stabilize oxygen: build and fuel an oxygen diffuser or algae terrarium.", "산소를 안정화하세요: 산소 발생기나 조류 테라리움을 짓고 자원을 공급하세요." },
            { "Control pressure: build a Manual Airlock to slow gas and heat exchange between rooms.", "압력을 제어하세요: 수동 에어록으로 방 사이의 기체와 열 교환을 늦추세요." },
            { "Inspect a Manual Airlock and close it to seal pathing, gas, and heat.", "수동 에어록을 Inspect한 뒤 닫아서 이동, 기체, 열을 차단하세요." },
            { "Control pressure: build a Manual or Mechanized Airlock to slow gas and heat exchange between rooms.", "압력을 제어하세요: 수동 또는 자동 에어록으로 방 사이의 기체와 열 교환을 늦추세요." },
            { "Build an airlock, then close it to prove room pressure control.", "에어록을 지은 뒤 닫아서 방 압력 제어를 증명하세요." },
            { "Close a Manual Airlock or send red automation to a Mechanized Airlock.", "수동 에어록을 닫거나 자동 에어록에 빨간 자동화 신호를 보내세요." },
            { "Keep an airlock closed to prove room pressure control.", "방 압력 제어를 증명하도록 에어록 하나를 닫아 두세요." },
            { "Inspect an airlock and set Access to a one-way or locked duplicant permission.", "에어록을 조사하고 Access를 일방향 또는 잠금 복제체 권한으로 설정하세요." },
            { "Build Gas Pump, Gas Pipe, and Gas Vent to route breathable air.", "가스 펌프, 가스 배관, 가스 배출구를 지어 숨쉴 공기를 라우팅하세요." },
            { "Build a Liquid Reservoir or Gas Reservoir on a pipe network to buffer flow.", "배관망에 액체 저장소나 가스 저장소를 지어 흐름을 완충하세요." },
            { "Build an Electrolyzer and Carbon Skimmer to process water into oxygen and scrub CO2.", "전해조와 탄소 스키머를 지어 물을 산소로 바꾸고 CO2를 제거하세요." },
            { "Build a Water Sieve to recycle polluted water back into clean water.", "정수기를 지어 오염된 물을 깨끗한 물로 재활용하세요." },
            { "Build a Medical Cot to treat sick or injured duplicants.", "아프거나 다친 복제체를 치료할 의료 침대를 지으세요." },
            { "Research Food Preparation, then build a Microbe Musher.", "음식 준비를 연구한 뒤 미생물 분쇄기를 지으세요." },
            { "Research Food Preparation, then build a Microbe Musher or Egg Cracker.", "음식 준비를 연구한 뒤 미생물 분쇄기나 알 깨기를 지으세요." },
            { "Research Food Preparation, then build a Microbe Musher, Egg Cracker, or Electric Grill.", "음식 준비를 연구한 뒤 미생물 분쇄기, 알 깨기, 전기 그릴 중 하나를 지으세요." },
            { "Preserve food: build and power a Refrigerator before stored meals spoil.", "음식을 보존하세요: 식사가 상하기 전에 냉장고를 짓고 전력을 공급하세요." },
            { "Preserve food: build a Ration Box early or power a Refrigerator for stronger cooling.", "음식을 보존하세요: 초반에는 식량 상자를 짓고, 더 강한 냉각이 필요하면 냉장고에 전력을 공급하세요." },
            { "Build one Mess Table per duplicant so meals improve morale.", "식사가 사기를 올리도록 복제체마다 식탁 1개를 지으세요." },
            { "Train a duplicant to Skill Lv 3 by completing skilled work.", "숙련 작업을 완료해 복제체 하나를 스킬 Lv 3까지 훈련하세요." },
            { "Decorate living areas with Decor Plants to raise morale and reduce stress.", "생활 구역을 장식 식물로 꾸며 사기를 올리고 스트레스를 줄이세요." },
            { "Decorate living areas with Decor Plants or powered Ceiling Lights to raise morale and reduce stress.", "생활 구역을 장식 식물이나 전력 공급된 천장 조명으로 꾸며 사기를 올리고 스트레스를 줄이세요." },
            { "Decorate living areas with Decor Plants, Sculpting Blocks, or powered Ceiling Lights to raise morale and reduce stress.", "생활 구역을 장식 식물, 조각 블록, 전력 공급된 천장 조명으로 꾸며 사기를 올리고 스트레스를 줄이세요." },
            { "Improve morale with Mess Halls, Barracks, Decor Plants, Water Coolers, and Massage Tables until skill needs are met.", "식당, 막사, 장식 식물, 물 냉각기, 마사지 침대로 스킬 사기 요구량을 충족하세요." },
            { "Improve morale with Mess Halls, Barracks, Decor Plants, Sculpting Blocks, Water Coolers, and Massage Tables until skill needs are met.", "식당, 막사, 장식 식물, 조각 블록, 물 냉각기, 마사지 침대로 스킬 사기 요구량을 충족하세요." },
            { "Improve morale with Mess Halls, Barracks, Decor Plants, Sculpting Blocks, Skill Scrubbers, Water Coolers, and Massage Tables until skill needs are met.", "식당, 막사, 장식 식물, 조각 블록, 스킬 세척기, 물 냉각기, 마사지 침대로 스킬 사기 요구량을 충족하세요." },
            { "Build a Skill Scrubber to reset over-skilled low-morale duplicants, or add decor and recreation.", "과하게 숙련되어 사기가 낮은 복제체의 스킬을 초기화하도록 스킬 세척기를 짓거나 장식과 휴식을 늘리세요." },
            { "Add stress care: build a Water Cooler or Massage Table and keep stress under 70%.", "스트레스 관리를 추가하세요: 물 냉각기나 마사지 침대를 짓고 스트레스를 70% 아래로 유지하세요." },
            { "Add stress care: build a Water Cooler, Massage Table, or Skill Scrubber and keep stress under 70%.", "스트레스 관리를 추가하세요: 물 냉각기, 마사지 침대, 스킬 세척기 중 하나를 짓고 스트레스를 70% 아래로 유지하세요." },
            { "Research Advanced Power so the colony can build an Arcade Cabinet.", "콜로니가 아케이드 캐비닛을 지을 수 있도록 고급 전력을 연구하세요." },
            { "Build and wire an Arcade Cabinet in a Recreation Room or Great Hall.", "휴게실이나 대형 식당에 아케이드 캐비닛을 짓고 전선을 연결하세요." },
            { "Connect the Arcade Cabinet to powered wire and keep automation green.", "아케이드 캐비닛을 전력 전선에 연결하고 자동화 신호를 초록으로 유지하세요." },
            { "Press petroleum into plastic so the Arcade Cabinet has replacement parts.", "아케이드 캐비닛의 교체 부품을 위해 석유를 플라스틱으로 압착하세요." },
            { "Let a stressed duplicant use the Arcade Cabinet during downtime.", "스트레스를 받은 복제체가 휴식 시간에 아케이드 캐비닛을 사용하게 하세요." },
            { "Secure food: grow mealwood, cook mush bars, crack hatch eggs, or grill quality meals until reserves stabilize.", "식량을 확보하세요: 식량 비축이 안정될 때까지 밀우드 재배, 머시바 조리, 해치 알 깨기, 고품질 식사 굽기를 하세요." },
            { "Secure food: grow mealwood or grubfruit, cook mush bars, crack hatch eggs, or grill quality meals until reserves stabilize.", "식량을 확보하세요: 비축량이 안정될 때까지 밀우드나 그럽프루트를 재배하고, 머시바를 조리하거나 해치 알을 깨거나 고품질 식사를 굽세요." },
            { "Restore crop oxygen, temperature, water, sulfur, and pressure so food plants can keep growing.", "식량 작물이 계속 자라도록 산소, 온도, 물, 황, 압력을 회복하세요." },
            { "Stabilize food safety: keep food fresh and below contamination by using storage, refrigeration, or sterile gas.", "식량 안전을 안정화하세요: 저장, 냉장, 무균 기체 보관으로 식량을 신선하고 오염도 낮게 유지하세요." },
            { "Build a Medical Cot so safety operations can handle injuries and disease.", "부상과 질병에 대응할 수 있도록 의료 침대를 지으세요." },
            { "Stabilize healthcare: treat sick duplicants at Medical Cots and keep medicine ready.", "의료 체계를 안정화하세요: 아픈 복제체를 의료 침대에서 치료하고 약품을 준비해 두세요." },
            { "Stabilize infrastructure: repair damage, mop flooding, cool overheating equipment, and vent dangerous pressure.", "기반시설을 안정화하세요: 손상을 수리하고 침수를 닦고 과열 설비를 식히며 위험 압력을 배출하세요." },
            { "Keep food safe, duplicants healthy, and infrastructure hazard-free to prove stable safety operations.", "식량 안전, 복제체 건강, 위험 없는 기반시설을 유지해 안전 운영 안정화를 증명하세요." },
            { "Research Food Preparation before improving crop tending.", "작물 돌봄을 개선하기 전에 음식 준비를 연구하세요." },
            { "Build a Farm Station near crops so duplicants can tend them.", "복제체가 작물을 돌볼 수 있도록 작물 근처에 농업 스테이션을 지으세요." },
            { "Keep polluted dirt or dirt available so the Farm Station can fertilize crops.", "농업 스테이션이 작물을 비료 처리할 수 있도록 오염된 흙이나 흙을 확보하세요." },
            { "Let a duplicant tend a crop from the Farm Station to speed up food production.", "복제체가 농업 스테이션에서 작물을 돌봐 식량 생산을 가속하게 하세요." },
            { "Research Food Preparation before growing bristle blossoms.", "브리슬 블로섬을 재배하기 전에 음식 준비를 연구하세요." },
            { "Build a Hydroponic Farm to grow bristle blossoms for higher-quality food.", "고품질 식량을 위해 브리슬 블로섬을 재배할 수경 농장을 지으세요." },
            { "Feed clean water into a Hydroponic Farm so bristle blossoms can grow.", "브리슬 블로섬이 자라도록 수경 농장에 깨끗한 물을 공급하세요." },
            { "Light a Hydroponic Farm with a Ceiling Light or shine bug so bristle blossoms can bloom.", "브리슬 블로섬이 꽃피도록 천장 조명이나 샤인 버그로 수경 농장을 밝히세요." },
            { "Let a lit Hydroponic Farm finish growing, then harvest bristle berries.", "밝혀진 수경 농장이 성장을 마치면 브리슬 베리를 수확하세요." },
            { "Keep bristle blossoms watered and lit until the berry harvest stocks quality food.", "브리슬 블로섬에 물과 빛을 유지해 베리 수확으로 고품질 식량을 비축하세요." },
            { "Research Food Preparation before growing dusk caps.", "더스크 캡을 재배하기 전에 음식 준비를 연구하세요." },
            { "Build a Fungal Farm in a dark CO2 pocket to grow dusk caps.", "더스크 캡을 재배할 수 있도록 어두운 CO2 주머니에 버섯 농장을 지으세요." },
            { "Collect slime so Fungal Farms can feed dusk caps.", "버섯 농장이 더스크 캡을 먹일 수 있도록 슬라임을 모으세요." },
            { "Keep a Fungal Farm in carbon dioxide so dusk caps can grow.", "더스크 캡이 자라도록 버섯 농장을 이산화탄소 안에 두세요." },
            { "Keep a Fungal Farm dark; dusk caps stop growing under light.", "버섯 농장을 어둡게 유지하세요. 더스크 캡은 빛 아래에서 성장을 멈춥니다." },
            { "Let a dark CO2 Fungal Farm consume slime, then harvest dusk caps.", "어두운 CO2 버섯 농장이 슬라임을 소비하게 한 뒤 더스크 캡을 수확하세요." },
            { "Keep dusk caps supplied with slime and CO2 until mushrooms stock the pantry.", "더스크 캡에 슬라임과 CO2를 공급해 버섯 식량을 비축하세요." },
            { "Research Food Preparation before growing grubfruit.", "그럽프루트를 재배하기 전에 음식 준비를 연구하세요." },
            { "Build or discover a Grubfruit Plant near sulfur to diversify food.", "식량 다양화를 위해 황 근처에 그럽프루트 식물을 짓거나 발견하세요." },
            { "Keep loose or stored sulfur near a Grubfruit Plant so it can grow.", "그럽프루트 식물이 자라도록 바닥 황이나 저장 황을 근처에 유지하세요." },
            { "Keep a Grubfruit Plant in mild gas pressure between 10C and 50C.", "그럽프루트 식물을 10C-50C의 온화한 기체 압력 안에 유지하세요." },
            { "Let a sulfur-fed Grubfruit Plant mature, then harvest grubfruit.", "황을 공급받는 그럽프루트 식물이 성숙하면 그럽프루트를 수확하세요." },
            { "Keep Grubfruit Plants supplied with sulfur until the harvest stocks quality food.", "고품질 식량을 비축할 때까지 그럽프루트 식물에 황을 공급하세요." },
            { "Research Food Preparation before growing thimble reeds.", "골무갈대를 재배하기 전에 음식 준비를 연구하세요." },
            { "Build or discover Thimble Reed near polluted water to produce reed fiber.", "갈대 섬유 생산을 위해 오염수 근처에 골무갈대를 짓거나 발견하세요." },
            { "Feed polluted water into Thimble Reed so it can grow reed fiber.", "골무갈대가 갈대 섬유를 자라게 하도록 오염수를 공급하세요." },
            { "Keep Thimble Reed in oxygen or polluted oxygen between 18C and 42C.", "골무갈대를 18C-42C의 산소 또는 오염 산소 안에 유지하세요." },
            { "Let a polluted-water Thimble Reed mature, then harvest reed fiber.", "오염수를 공급받는 골무갈대가 성숙하면 갈대 섬유를 수확하세요." },
            { "Harvest enough Thimble Reed fiber for textile and suit production.", "직물과 슈트 생산에 필요한 골무갈대 섬유를 충분히 수확하세요." },
            { "Research Food Preparation before growing sleet wheat.", "한랭 밀을 재배하기 전에 음식 준비를 연구하세요." },
            { "Build or discover Sleet Wheat in a freezing biome to grow wheat grain.", "밀알을 재배하도록 얼어붙은 생물군계에서 한랭 밀을 짓거나 발견하세요." },
            { "Keep Sleet Wheat supplied with clean water.", "한랭 밀에 깨끗한 물을 계속 공급하세요." },
            { "Keep Sleet Wheat between -55C and 5C with breathable oxygen.", "한랭 밀을 -55C에서 5C 사이의 호흡 가능한 산소 안에 유지하세요." },
            { "Let cold-water Sleet Wheat mature, then harvest wheat grain.", "찬물 공급을 받는 한랭 밀이 성숙하면 밀알을 수확하세요." },
            { "Build an Electric Grill so wheat grain can become frost buns.", "밀알을 서리빵으로 만들 수 있도록 전기 그릴을 지으세요." },
            { "Store enough wheat grain for the Electric Grill to bake frost buns.", "전기 그릴이 서리빵을 구울 수 있도록 밀알을 충분히 저장하세요." },
            { "Bake wheat grain into frost buns at an Electric Grill.", "전기 그릴에서 밀알을 서리빵으로 구우세요." },
            { "Research Food Preparation before growing pincha pepperplants.", "핀차 페퍼 식물을 재배하기 전에 음식 준비를 연구하세요." },
            { "Build a Pepper Plant in a warm room to grow peppernuts for seasoned meals.", "양념 식사용 페퍼넛을 재배하도록 따뜻한 방에 페퍼 식물을 지으세요." },
            { "Feed polluted water from storage or a nearby pipe into a Pepper Plant.", "저장소나 인접 배관의 오염수를 페퍼 식물에 공급하세요." },
            { "Keep a Pepper Plant warm; peppernuts grow best between 35C and 85C.", "페퍼 식물을 따뜻하게 유지하세요. 페퍼넛은 35C에서 85C 사이에서 가장 잘 자랍니다." },
            { "Let a warm polluted-water Pepper Plant mature, then harvest peppernuts.", "오염수를 공급받는 따뜻한 페퍼 식물이 성숙하면 페퍼넛을 수확하세요." },
            { "Build an Electric Grill so peppernuts can season cooked meals.", "페퍼넛으로 조리 식사를 양념할 수 있도록 전기 그릴을 지으세요." },
            { "Harvest enough peppernuts for the Electric Grill seasoning step.", "전기 그릴 양념 단계에 필요한 페퍼넛을 충분히 수확하세요." },
            { "Let the Electric Grill consume peppernuts and produce seasoned quality meals.", "전기 그릴이 페퍼넛을 소비해 양념 고품질 식사를 만들게 하세요." },
            { "Explore forest pockets to discover wild Arbor Trees.", "야생 아버 트리를 발견하도록 숲 포켓을 탐사하세요." },
            { "Free dry storage space before harvesting lumber from Arbor Trees.", "아버 트리에서 목재를 수확하기 전에 건식 저장 공간을 비우세요." },
            { "Harvest a mature Arbor Tree to stock lumber.", "성숙한 아버 트리를 수확해 목재를 비축하세요." },
            { "Keep Arbor Trees in mild gas pressure until one matures for lumber.", "목재 수확을 위해 아버 트리가 성숙할 때까지 온화한 기체 압력을 유지하세요." },
            { "Harvest enough Arbor Tree lumber to start the forestry supply chain.", "임업 공급망을 시작할 만큼 아버 트리 목재를 수확하세요." },
            { "Research Advanced Power before distilling lumber into ethanol fuel.", "목재를 에탄올 연료로 증류하기 전에 고급 전력을 연구하세요." },
            { "Build an Ethanol Distiller to turn lumber into petroleum-equivalent fuel.", "목재를 석유 등가 연료로 바꿀 에탄올 증류기를 지으세요." },
            { "Harvest or store lumber so the Ethanol Distiller can run.", "에탄올 증류기가 가동되도록 목재를 수확하거나 저장하세요." },
            { "Keep the Ethanol Distiller wired, powered, enabled, and dry while it converts lumber into fuel.", "에탄올 증류기가 목재를 연료로 바꾸는 동안 전선, 전력, 활성화 상태와 건조 상태를 유지하세요." },
            { "Let the Ethanol Distiller convert enough lumber into fuel for the petroleum loop.", "에탄올 증류기가 석유 루프에 쓸 만큼 목재를 연료로 전환하게 두세요." },
            { "Create a power buffer: add battery capacity and store 75 power.", "전력 완충을 만드세요: 배터리 용량을 늘리고 전력 75를 저장하세요." },
            { "Create a power buffer: add Battery or Jumbo Battery capacity and store 75 power.", "전력 완충을 만드세요: 배터리나 대형 배터리 용량을 늘리고 전력 75를 저장하세요." },
            { "Wire the power grid: connect generators, batteries, and powered machines.", "전력망을 배선하세요: 발전기, 배터리, 전력 기계를 연결하세요." },
            { "Research Power Regulation so the grid can handle heavier machine loads.", "전력 제어를 연구해 전력망이 더 큰 기계 부하를 견디게 하세요." },
            { "Build a Coal Generator, mine coal, and let it produce backup power.", "석탄 발전기를 짓고 석탄을 채굴해 예비 전력을 생산하세요." },
            { "Build and power a Rock Crusher, then refine metal ore into Refined Metal.", "암석 분쇄기를 짓고 전력을 공급해 금속 원석을 제련 금속으로 바꾸세요." },
            { "Research Power Regulation before building a Metal Refinery.", "금속 정제기를 짓기 전에 전력 제어를 연구하세요." },
            { "Build and wire a Metal Refinery to automate high-yield metal refining.", "고수율 금속 정제를 자동화할 금속 정제기를 짓고 배선하세요." },
            { "Mine metal ore so the Metal Refinery has raw material.", "금속 정제기가 사용할 원료 금속 원석을 채굴하세요." },
            { "Store clean water or pipe it beside the Metal Refinery as coolant.", "냉각수로 쓸 깨끗한 물을 저장하거나 금속 정제기 옆으로 배관하세요." },
            { "Free dry storage space so the Metal Refinery can store Refined Metal.", "금속 정제기가 제련 금속을 보관할 수 있도록 건식 저장 공간을 비우세요." },
            { "Keep the Metal Refinery powered and automation green while coolant flows.", "냉각수가 흐르는 동안 금속 정제기에 전력과 초록 자동화 신호를 유지하세요." },
            { "Let the Metal Refinery turn metal ore and coolant into Refined Metal and polluted water.", "금속 정제기가 금속 원석과 냉각수를 제련 금속과 오염수로 바꾸게 두세요." },
            { "Build and wire a Metal Refinery before alloying steel.", "강철을 합금하기 전에 금속 정제기를 짓고 전선을 연결하세요." },
            { "Refine or recover more Refined Metal so the Metal Refinery can alloy steel without draining the reserve.", "금속 정제기가 비축분을 소진하지 않고 강철을 합금할 수 있도록 제련 금속을 더 만들거나 회수하세요." },
            { "Store coal so the Metal Refinery can alloy it with Refined Metal into steel.", "금속 정제기가 제련 금속과 합금해 강철을 만들 수 있도록 석탄을 저장하세요." },
            { "Store clean water or pipe it beside the Metal Refinery as steel coolant.", "강철 냉각수로 쓸 깨끗한 물을 저장하거나 금속 정제기 옆으로 배관하세요." },
            { "Free dry storage space so the Metal Refinery can store steel.", "금속 정제기가 강철을 보관할 수 있도록 건식 저장 공간을 비우세요." },
            { "Keep the Metal Refinery powered and automation green while steel alloying runs.", "강철 합금이 진행되는 동안 금속 정제기에 전력과 초록 자동화 신호를 유지하세요." },
            { "Let the Metal Refinery alloy Refined Metal, coal, and coolant into steel.", "금속 정제기가 제련 금속, 석탄, 냉각수를 강철로 합금하게 두세요." },
            { "metal refinery needs refined metal for steel", "금속 정제기에 강철용 제련 금속 필요" },
            { "metal refinery needs coal for steel", "금속 정제기에 강철용 석탄 필요" },
            { "metal refinery needs steel coolant", "금속 정제기에 강철 냉각수 필요" },
            { "metal refinery needs niobium for thermium", "금속 정제기에 테르밈용 니오븀 필요" },
            { "metal refinery needs extra steel for thermium", "금속 정제기에 테르밈용 추가 강철 필요" },
            { "metal refinery needs thermium coolant", "금속 정제기에 테르밈 냉각수 필요" },
            { "metal refinery needs fullerene for super coolant", "금속 정제기에 초냉매용 풀러렌 필요" },
            { "metal refinery needs thermium for super coolant", "금속 정제기에 초냉매용 테르밈 필요" },
            { "metal refinery needs petroleum for super coolant", "금속 정제기에 초냉매용 석유 필요" },
            { "metal refinery needs super coolant water feed", "금속 정제기에 초냉매용 물 공급 필요" },
            { "super coolant loop idle", "초냉매 루프 유휴 상태" },
            { "thermo regulator needs super coolant for cryogenic propellant", "열 조절기에 극저온 추진제용 초냉매 필요" },
            { "thermo regulator needs piped oxygen for cryogenic propellant", "열 조절기에 극저온 추진제용 배관 산소 필요" },
            { "thermo regulator needs piped hydrogen for cryogenic propellant", "열 조절기에 극저온 추진제용 배관 수소 필요" },
            { "cryogenic propellant storage full", "극저온 추진제 저장 공간 가득 참" },
            { "cryogenic propellant plant idle", "극저온 추진제 설비 유휴 상태" },
            { "Build four Insulated Tiles to separate living rooms from dangerous heat and gas.", "단열 타일 4개로 생활 공간을 위험한 열과 기체에서 분리하세요." },
            { "Research Thermal Engineering before producing ceramic insulation.", "세라믹 단열재를 만들기 전에 열 공학을 연구하세요." },
            { "Build and power a Rock Crusher so duplicants can fire dirt and coal into ceramic.", "복제체가 흙과 석탄을 세라믹으로 구울 수 있도록 암석 분쇄기를 짓고 전력을 공급하세요." },
            { "Store dirt so the Rock Crusher can fire ceramic for better insulation.", "암석 분쇄기가 더 좋은 단열용 세라믹을 구울 수 있도록 흙을 저장하세요." },
            { "Store coal so the Rock Crusher can fire ceramic insulation.", "암석 분쇄기가 세라믹 단열재를 구울 수 있도록 석탄을 저장하세요." },
            { "Free dry storage space so ceramic can be stored before insulation retrofit.", "단열 개량 전에 세라믹을 저장할 수 있도록 건식 저장 공간을 비우세요." },
            { "Let the Rock Crusher fire ceramic, then existing Insulated Tiles will retrofit automatically.", "암석 분쇄기가 세라믹을 굽게 두세요. 기존 단열 타일이 자동으로 개량됩니다." },
            { "Build more Insulated Tiles so stored ceramic can retrofit them into high-grade insulation.", "저장된 세라믹이 고급 단열로 개량할 수 있도록 단열 타일을 더 지으세요." },
            { "Keep the Rock Crusher powered and automation green while ceramic insulation is fired.", "세라믹 단열재를 굽는 동안 암석 분쇄기에 전력과 초록 자동화 신호를 유지하세요." },
            { "Produce enough ceramic to upgrade four Insulated Tiles into high-grade insulation.", "단열 타일 4개를 고급 단열로 개량할 만큼 세라믹을 생산하세요." },
            { "rock crusher needs dirt for ceramic", "암석 분쇄기에 세라믹용 흙 필요" },
            { "rock crusher needs coal for ceramic", "암석 분쇄기에 세라믹용 석탄 필요" },
            { "ceramic output storage full", "세라믹 출력 저장 공간 가득 참" },
            { "ceramic kiln needs power", "세라믹 소성에 전력 필요" },
            { "no glass production", "유리 생산 없음" },
            { "rock crusher needs dirt for glass", "암석 분쇄기에 유리용 흙 필요" },
            { "rock crusher needs ceramic flux for glass", "암석 분쇄기에 유리용 세라믹 플럭스 필요" },
            { "glass output storage full", "유리 출력 저장 공간 가득 참" },
            { "glass melting needs power", "유리 용융에 전력 필요" },
            { "Create separate Barracks and Mess Hall rooms with tiles, airlocks, or insulated walls.", "타일, 에어록, 단열 벽으로 막사와 식당을 별도 방으로 만드세요." },
            { "Seal beds behind tiles or airlocks to form a Barracks or Bedroom.", "침대를 타일이나 에어록 안에 밀폐해 막사나 침실을 만드세요." },
            { "Seal Mess Tables into a Mess Hall or Great Hall so meals improve morale.", "식탁을 밀폐해 식당이나 대형 식당을 만들고 식사 사기를 올리세요." },
            { "Seal toilets with basins, sanitizer, or showers to form a Washroom.", "화장실을 세면대, 손 소독기, 샤워기와 함께 밀폐해 화장실 방을 만드세요." },
            { "Build a Storage Bin, then enclose it as a Storage Room for organized resources.", "저장고를 지은 뒤 자원을 정리할 창고 방으로 밀폐하세요." },
            { "Seal Storage Bins or Ration Boxes into a Storage Room for better dry capacity.", "저장고나 식량 상자를 밀폐해 건식 저장 용량이 늘어나는 창고 방을 만드세요." },
            { "Split mixed rooms with tiles or airlocks so specialty room bonuses activate.", "혼합 방을 타일이나 에어록으로 나눠 전문 방 보너스를 활성화하세요." },
            { "Seal Medical Cots and Apothecaries into a Clinic to speed recovery.", "의료 침대와 약제소를 밀폐해 회복이 빨라지는 진료실을 만드세요." },
            { "Seal recreation fixtures into a Recreation Room or Great Hall for stronger stress relief.", "휴게 설비를 휴게실이나 대형 식당으로 밀폐해 스트레스 해소를 강화하세요." },
            { "Seal Ranching Stations and feeders into Stable rooms before critter output falls.", "크리터 생산량이 떨어지기 전에 목축 스테이션과 먹이통을 마구간 방으로 밀폐하세요." },
            { "Seal generators with a Power Control Station into a Power Plant to extend tune-ups.", "발전기와 전력 제어 스테이션을 발전실로 밀폐해 조정 지속 시간을 늘리세요." },
            { "Specialize core rooms: keep sleep, dining, washroom, and storage spaces enclosed and unmixed.", "핵심 방을 전문화하세요: 수면, 식사, 화장실, 창고 공간을 밀폐하고 섞이지 않게 유지하세요." },
            { "Seal the Ranching Station into a Stable room so grooming and coal output improve.", "목축 스테이션을 마구간 방으로 밀폐해 털손질과 석탄 생산을 개선하세요." },
            { "Use Deconstruct on a building or conduit to recover materials and reconfigure the base.", "건물이나 도관에 Deconstruct를 사용해 재료를 회수하고 기지를 재구성하세요." },
            { "Keep a Printing Pod open until it prints a fourth duplicant.", "프린팅 포드를 열어 네 번째 복제체가 출력될 때까지 유지하세요." },
            { "Build Fire Poles beside the main ladder shaft to speed downward commutes.", "아래 방향 통근을 빠르게 하도록 주 사다리 통로 옆에 소방 봉을 지으세요." },
            { "Extend a continuous Fire Pole spine through at least four vertical tiles.", "연속된 소방 봉 축을 세로 4칸 이상으로 확장하세요." },
            { "Send duplicants down the Fire Pole spine until vertical transit is proven.", "수직 이동이 증명될 때까지 복제체를 소방 봉 축 아래로 이동시키세요." },
            { "Shorten severe long commutes with more ladders, floors, doors, or Fire Poles.", "사다리, 바닥, 문, 소방 봉을 추가해 심각한 긴 통근을 줄이세요." },
            { "Keep the Fire Pole transit spine available so duplicants can move quickly between floors.", "복제체가 층 사이를 빠르게 오갈 수 있도록 소방 봉 이동축을 열어 두세요." },
            { "Automate power: research Power Regulation, then link a Smart Battery to a generator with Automation Wire.", "전력을 자동화하세요: 전력 제어를 연구하고 스마트 배터리를 자동화 전선으로 발전기에 연결하세요." },
            { "Automate power: link a Smart Battery to a generator with Automation Wire.", "전력을 자동화하세요: 스마트 배터리를 자동화 전선으로 발전기에 연결하세요." },
            { "Research Automation Logistics, then link a Smart Battery to a generator with Automation Wire.", "자동화 물류를 연구한 뒤 스마트 배터리를 자동화 전선으로 발전기에 연결하세요." },
            { "Finish transformer load management before proving automated power recovery.", "자동 전력 복구를 증명하기 전에 변압기 부하 관리를 끝내세요." },
            { "Link a Smart Battery to at least one generator before proving automated power recovery.", "자동 전력 복구를 증명하기 전에 스마트 배터리를 발전기 하나 이상에 연결하세요." },
            { "Wire remaining powered buildings before proving automated power recovery.", "자동 전력 복구를 증명하기 전에 남은 전력 건물을 배선하세요." },
            { "Clear wire overloads before proving automated power recovery.", "자동 전력 복구를 증명하기 전에 전선 과부하를 해결하세요." },
            { "Recharge batteries above 35% while automated generators stay linked.", "자동화 발전기 연결을 유지한 채 배터리를 35% 이상 충전하세요." },
            { "Keep the automated grid stable without overloads until power recovery is proven.", "전력 복구가 증명될 때까지 과부하 없이 자동 전력망을 안정적으로 유지하세요." },
            { "Research Automation Logistics so the colony can build manual automation controls.", "자동화 물류를 연구해 수동 자동화 제어 장치를 지으세요." },
            { "Research Automation Logistics so the colony can automate debris cleanup.", "자동화 물류를 연구해 잔해 청소를 자동화하세요." },
            { "Research Automation Logistics so the colony can build conveyor shipping.", "자동화 물류를 연구해 컨베이어 물류를 구축하세요." },
            { "Research Automation Logistics so pipe sensors can drive shutoff valves.", "자동화 물류를 연구해 배관 센서가 차단 밸브를 제어하게 하세요." },
            { "Research Advanced Power so the colony can burn hydrogen and natural gas.", "고급 전력을 연구해 수소와 천연가스를 발전 연료로 쓰세요." },
            { "Natural gas found: research Advanced Power before building a Natural Gas Generator.", "천연가스 발견: 천연가스 발전기를 짓기 전에 고급 전력을 연구하세요." },
            { "Research Air Systems so duplicants can use Oxygen Masks in low oxygen.", "공기 시스템을 연구해 복제체가 저산소 구역에서 산소 마스크를 사용하게 하세요." },
            { "Build an Oxygen Mask Dock near breathable oxygen.", "호흡 가능한 산소 근처에 산소 마스크 도크를 지으세요." },
            { "Build an Oxygen Mask Checkpoint beside a dock to control low oxygen entry.", "저산소 구역 출입을 제어하도록 도크 옆에 산소 마스크 체크포인트를 지으세요." },
            { "The Oxygen Mask Checkpoint is blocking low oxygen entry; charge the dock with oxygen.", "산소 마스크 체크포인트가 저산소 구역 진입을 막고 있습니다. 도크에 산소를 충전하세요." },
            { "Let the Oxygen Mask Dock charge from local breathable oxygen before crossing the checkpoint.", "체크포인트를 건너기 전에 산소 마스크 도크가 주변 호흡 가능 산소로 충전되게 하세요." },
            { "Wait for a duplicant to return an Oxygen Mask or build another dock before sending more workers through.", "추가 복제체를 보내기 전에 산소 마스크가 반납되기를 기다리거나 도크를 하나 더 지으세요." },
            { "Send a duplicant through the Oxygen Mask Checkpoint into low oxygen to use mask oxygen.", "복제체를 산소 마스크 체크포인트 너머 저산소 구역으로 보내 마스크 산소를 사용하게 하세요." },
            { "Research Thermal Engineering so duplicants can use Atmo Suits and insulation.", "열 공학을 연구해 복제체가 대기복과 단열을 사용하게 하세요." },
            { "Wait for a duplicant to return an Atmo Suit or build another dock before sending more workers through.", "추가 복제체를 보내기 전에 대기복이 반납되기를 기다리거나 도크를 하나 더 지으세요." },
            { "Research Advanced Power so the colony can build a Steam Turbine.", "고급 전력을 연구해 증기 터빈을 지으세요." },
            { "Research Space Systems so the colony can build Solar Panels.", "우주 시스템을 연구해 태양광 패널을 지으세요." },
            { "Finish ceramic insulation before producing solar glass lenses.", "태양광 유리 렌즈를 만들기 전에 세라믹 단열을 완료하세요." },
            { "Build and power a Rock Crusher so duplicants can melt solar glass.", "복제체가 태양광 유리를 녹일 수 있도록 암석 분쇄기를 짓고 전력을 공급하세요." },
            { "Build a Solar Panel so glass lenses have a target.", "유리 렌즈를 설치할 대상이 있도록 태양광 패널을 지으세요." },
            { "Build a second Solar Panel so the colony can install enough glass lenses.", "충분한 유리 렌즈를 설치할 수 있도록 두 번째 태양광 패널을 지으세요." },
            { "Expose a Solar Panel to open sky before installing glass lenses.", "유리 렌즈를 설치하기 전에 태양광 패널을 열린 하늘에 노출하세요." },
            { "Store dirt so the Rock Crusher can melt glass.", "암석 분쇄기가 유리를 녹일 수 있도록 흙을 저장하세요." },
            { "Keep some ceramic available as flux for solar glass.", "태양광 유리 플럭스로 쓸 세라믹을 조금 남겨 두세요." },
            { "Free dry storage space so glass can be stored for solar lenses.", "태양광 렌즈용 유리를 저장할 수 있도록 건식 저장 공간을 비우세요." },
            { "Keep the Rock Crusher powered and automation green while glass is melted.", "유리를 녹이는 동안 암석 분쇄기에 전력과 초록 자동화 신호를 유지하세요." },
            { "Let the Rock Crusher melt glass before solar panels install lenses.", "태양광 패널이 렌즈를 설치하기 전에 암석 분쇄기가 유리를 녹이게 두세요." },
            { "Keep sky-exposed Solar Panels running while they install glass lenses.", "하늘에 노출된 태양광 패널이 유리 렌즈를 설치하는 동안 계속 작동하게 하세요." },
            { "Research Space Systems so the colony can build meteor shielding.", "우주 시스템을 연구해 운석 방어를 구축하세요." },
            { "Research Space Systems so the colony can scan for meteor showers.", "우주 시스템을 연구해 운석우를 스캔하세요." },
            { "Build Bunker Doors above exposed surface infrastructure before the next meteor shower.", "다음 운석우 전에 노출된 지상 설비 위에 벙커 문을 지으세요." },
            { "Let a meteor shower deposit regolith so the surface recovery loop can be verified.", "표면 복구 루프를 검증할 수 있도록 운석우가 레골리스를 쌓게 하세요." },
            { "Dig meteor regolith off the surface so solar panels, scanners, and bunker doors stay clear.", "태양광 패널, 스캐너, 벙커 문이 막히지 않도록 표면의 운석 레골리스를 파내세요." },
            { "Repair damaged Bunker Doors before the next meteor shower arrives.", "다음 운석우가 오기 전에 손상된 벙커 문을 수리하세요." },
            { "Keep the recovered surface clear and repaired until recovery is recorded.", "복구가 기록될 때까지 복구된 표면을 깨끗하고 수리된 상태로 유지하세요." },
            { "Complete meteor shielding before automating surface defense.", "지표면 방어를 자동화하기 전에 운석 방어를 완료하세요." },
            { "Complete space scanning before automating Bunker Doors.", "벙커 문을 자동화하기 전에 우주 스캐닝을 완료하세요." },
            { "Link Space Scanner automation to Bunker Doors so warning signals close the surface.", "경보 신호가 지표면을 닫도록 우주 스캐너 자동화를 벙커 문에 연결하세요." },
            { "Wait for an incoming meteor warning so the Space Scanner can close Bunker Doors.", "우주 스캐너가 벙커 문을 닫을 수 있도록 다가오는 운석 경보를 기다리세요." },
            { "Hold Bunker Doors closed by scanner automation until the automated meteor defense is proven.", "자동 운석 방어가 입증될 때까지 스캐너 자동화로 벙커 문을 닫아 두세요." },
            { "Explore cold upper biomes to discover wheezeworts for passive cooling.", "수동 냉각을 위해 차가운 상층 생물군계를 탐사해 위즈워트를 발견하세요." },
            { "Keep a wheezewort in hydrogen so it can remove heat efficiently.", "위즈워트가 열을 효율적으로 제거하도록 수소 안에 유지하세요." },
            { "Let a wheezewort cool nearby gas until its passive cooling is proven.", "위즈워트가 주변 기체를 냉각해 수동 냉각이 입증될 때까지 기다리세요." },
            { "Explore upper hydrogen pockets to uncover an Anti Entropy Thermo-Nullifier.", "상층 수소 포켓을 탐사해 엔트로피 무효화 장치를 발견하세요." },
            { "Research Thermal Engineering before building a controlled AETN cooling chamber.", "제어된 AETN 냉각실을 만들기 전에 열 공학을 연구하세요." },
            { "Build Gas Pipe and a Gas Vent so hydrogen can be delivered beside the AETN.", "AETN 옆으로 수소를 보낼 수 있도록 가스 배관과 가스 배출구를 지으세요." },
            { "Vent hydrogen beside the AETN or open a hydrogen pocket so it can start deleting heat.", "AETN 옆에 수소를 배출하거나 수소 포켓을 열어 열 제거를 시작하게 하세요." },
            { "Warm the AETN chamber above its dormant threshold while hydrogen is available.", "수소가 있는 상태에서 AETN 냉각실을 휴면 임계값보다 따뜻하게 유지하세요." },
            { "Keep feeding hydrogen to the AETN until its fuel consumption is proven.", "연료 소비가 입증될 때까지 AETN에 수소를 계속 공급하세요." },
            { "Let the AETN remove heat from the chamber until its cooling output is proven.", "냉각 출력이 입증될 때까지 AETN이 냉각실에서 열을 제거하게 두세요." },
            { "Research Thermal Engineering before building an active coolant loop.", "능동 냉각수 루프를 짓기 전에 열 공학을 연구하세요." },
            { "Build a Thermo Aquatuner and connect liquid pipes for an active coolant loop.", "능동 냉각수 루프를 위해 액체 냉각기를 짓고 액체 배관을 연결하세요." },
            { "Run enough Liquid Pipe through the Thermo Aquatuner input and output to form a coolant loop.", "냉각수 루프가 되도록 액체 냉각기의 입력과 출력에 충분한 액체 배관을 연결하세요." },
            { "Feed liquid into the Thermo Aquatuner and leave output pipe capacity for cooled coolant.", "액체 냉각기에 액체를 공급하고 냉각된 냉각수가 나갈 출력 배관 용량을 비워 두세요." },
            { "Move coolant away from freezing or boiling temperatures before pipes rupture.", "배관이 파열되기 전에 냉각수를 동결/비등 온도에서 벗어나게 하세요." },
            { "Let the Thermo Aquatuner process coolant until active cooling is established.", "능동 냉각이 구축될 때까지 액체 냉각기가 냉각수를 처리하게 두세요." },
            { "Keep the coolant loop running without pipe or reservoir ruptures until stability is proven.", "안정성이 증명될 때까지 배관이나 저장소 파열 없이 냉각수 루프를 계속 가동하세요." },
            { "Finish the active coolant loop before enclosing a hot industrial sauna.", "뜨거운 산업 사우나를 밀폐하기 전에 능동 냉각수 루프를 완료하세요." },
            { "Research Advanced Power and Thermal Engineering before building an industrial sauna.", "산업 사우나를 짓기 전에 고급 전력과 열 공학을 연구하세요." },
            { "Add more Insulated Tiles around the industrial room before trapping heat and steam.", "열과 증기를 가두기 전에 산업 방 주변에 단열 타일을 더 추가하세요." },
            { "Place a Metal Refinery, Oil Refinery, Polymer Press, Petroleum Generator, Aquatuner, or Sour Gas Condenser inside a machine room.", "기계실 안에 금속 정련기, 정유기, 폴리머 압착기, 석유 발전기, 액체 냉각기, 또는 사워 가스 응축기를 배치하세요." },
            { "Place a Metal Refinery, Oil Refinery, Ethanol Distiller, Polymer Press, Petroleum Generator, Aquatuner, or Sour Gas Condenser inside a machine room.", "기계실 안에 금속 정련기, 정유기, 에탄올 증류기, 폴리머 압착기, 석유 발전기, 액체 냉각기, 또는 사워 가스 응축기를 배치하세요." },
            { "Enclose a hot Machine Room or Power Plant with steam so industrial heat can be recovered.", "산업 열을 회수할 수 있도록 뜨거운 기계실이나 발전소를 증기로 밀폐하세요." },
            { "Power and fuel one industrial machine inside the hot steam room.", "뜨거운 증기 방 안의 산업 기계 하나에 전력과 연료를 공급하세요." },
            { "Wire a Steam Turbine close enough to hot steam to recover industrial heat.", "산업 열을 회수하도록 뜨거운 증기 근처에 증기 터빈을 배선하세요." },
            { "Let the Steam Turbine recover more heat from the industrial sauna.", "증기 터빈이 산업 사우나의 열을 더 회수하게 하세요." },
            { "Repair broken machinery before proving the industrial sauna.", "산업 사우나를 증명하기 전에 고장난 기계를 수리하세요." },
            { "Stabilize coolant pipes before proving the industrial sauna.", "산업 사우나를 증명하기 전에 냉각수 배관을 안정화하세요." },
            { "Pull duplicants out of scalding heat or route them through suits before proving the sauna.", "사우나를 증명하기 전에 복제체를 고열에서 빼내거나 보호복 경로로 보내세요." },
            { "Keep the hot industrial room, coolant loop, and Steam Turbine stable until the sauna is proven.", "사우나가 증명될 때까지 뜨거운 산업 방, 냉각수 루프, 증기 터빈을 안정적으로 유지하세요." },
            { "Stabilize temperature: build heaters, thermo regulators, or tempshift plates to keep living areas safe.", "온도를 안정화하세요: 히터, 열 조절기, 열 전도판을 지어 생활 구역을 안전하게 유지하세요." },
            { "Stabilize temperature: build heaters, thermo regulators, aquatuners, or tempshift plates to keep living areas safe.", "온도를 안정화하세요: 히터, 열 조절기, 액체 냉각기, 열 전도판을 지어 생활 구역을 안전하게 유지하세요." },
            { "Complete safety operations before proving long-term sustainability.", "장기 지속성을 증명하기 전에 안전 운영을 완료하세요." },
            { "Specialize core rooms before proving long-term sustainability.", "장기 지속성을 증명하기 전에 핵심 방을 전문화하세요." },
            { "Finish a full cycle without food, water, power, or oxygen deficits to start sustainability tracking.", "지속성 추적을 시작하려면 식량, 물, 전력, 산소 부족 없이 한 사이클을 마치세요." },
            { "Maintain stable food, water, power, oxygen, health, and infrastructure for three consecutive cycles.", "식량, 물, 전력, 산소, 건강, 기반시설을 3사이클 연속 안정적으로 유지하세요." },
            { "Prove long-term sustainability before dedicating the colony monument.", "콜로니 기념비를 봉헌하기 전에 장기 지속성을 증명하세요." },
            { "Finish three Sculpting Blocks as a colony monument before closing the charter.", "헌장을 마무리하기 전에 조각 블록 3개를 완성해 콜로니 기념비로 삼으세요." },
            { "Seal recreation fixtures into a Recreation Room or Great Hall for the colony monument ceremony.", "콜로니 기념비 의식을 위해 휴게 설비를 휴게실이나 대강당으로 밀폐하세요." },
            { "Seal recreation fixtures into a Recreation Room or Great Hall before the monument ceremony.", "기념비 의식 전에 휴게 설비를 휴게실이나 대강당으로 밀폐하세요." },
            { "Add Decor Plants, powered Ceiling Lights, or finished Sculpting Blocks along daily routes.", "일상 동선에 장식 식물, 전원이 연결된 천장등, 완성된 조각 블록을 추가하세요." },
            { "Add Decor Plants, powered Ceiling Lights, or finished Sculpting Blocks along daily routes before the monument ceremony.", "기념비 의식 전에 일상 동선에 장식 식물, 전원이 연결된 천장등, 완성된 조각 블록을 추가하세요." },
            { "Raise duplicant morale before dedicating the colony monument.", "콜로니 기념비를 봉헌하기 전에 복제체 사기를 높이세요." },
            { "Raise duplicant morale before holding the monument ceremony.", "기념비 의식을 열기 전에 복제체 사기를 높이세요." },
            { "Lower colony stress before holding the monument ceremony.", "기념비 의식을 열기 전에 콜로니 스트레스를 낮추세요." },
            { "Lower stress with downtime, decor, recreation, and massage before the monument ceremony.", "기념비 의식 전에 휴식 시간, 장식, 휴게, 마사지로 스트레스를 낮추세요." },
            { "Repair broken equipment before holding the monument ceremony.", "기념비 의식을 열기 전에 고장난 장비를 수리하세요." },
            { "Shorten severe commutes before holding the monument ceremony.", "기념비 의식을 열기 전에 심한 장거리 통근을 줄이세요." },
            { "Hold the colony stable while duplicants dedicate the colony monument.", "복제체가 콜로니 기념비를 봉헌하는 동안 콜로니를 안정적으로 유지하세요." },
            { "Hold stable morale, decor, rooms, commutes, and repairs for ", "사기, 장식, 방, 통근, 수리 상태를 " },
            { " more second(s) to dedicate the colony monument.", "초 더 안정적으로 유지해 콜로니 기념비를 봉헌하세요." },
            { "Survive until cycle 5 with at least one active duplicant.", "활동 가능한 복제체 1명 이상으로 5사이클까지 생존하세요." },
            { "Colony failed. Load a save or start a new run from the editor.", "콜로니가 실패했습니다. 저장 파일을 불러오거나 새 런을 시작하세요." },
            { "Colony failed. Load a save or start a new run.", "콜로니가 실패했습니다. 저장 파일을 불러오거나 새 런을 시작하세요." },

