            { "Stable bonus: slicksters stay happier and produce more crude oil.", "마구간 보너스: 슬릭스터가 더 행복하게 지내고 원유를 더 생산합니다." },
            { "Stable bonus: dreckos stay happier and shed more plastic.", "마구간 보너스: 드레코가 더 행복하게 지내고 플라스틱을 더 많이 배출합니다." },
            { "Stable bonus: pufts stay happier and produce more slime.", "마구간 보너스: 퍼프가 더 행복하게 지내고 슬라임을 더 생산합니다." },
            { "Stable grooming keeps morbs calmer and lowers emissions.", "마구간 돌봄은 모브를 진정시켜 배출량을 줄입니다." },
            { "Stable grooming keeps pacu calmer and improves seafood output.", "마구간 돌봄은 파쿠를 진정시켜 해산물 생산을 높입니다." },
            { "Stable grooming keeps shine bugs bright for work and farms.", "마구간 돌봄은 샤인 버그를 밝게 유지해 작업과 농사를 돕습니다." },
            { "Stable grooming keeps pips planting and producing dirt.", "마구간 돌봄은 핍이 식재하고 흙을 만들도록 유지합니다." },
            { "Provides living light for decor, work speed, and crop growth without power.", "전력 없이 장식, 작업 속도, 작물 성장에 도움이 되는 생체 조명을 제공합니다." },
            { "Feeds on lumber or Arbor Tree growth, produces dirt, and plants wild Arbor Trees in forest pockets.", "목재나 아버 트리 성장을 먹고 흙을 만들며, 숲 포켓에 야생 아버 트리를 심습니다." },
            { "Offspring need happy, groomed, uncrowded critters and nearby habitat space.", "새끼를 낳으려면 행복하고 돌봄받은 비과밀 크리터와 주변 서식 공간이 필요합니다." },
            { "Stable bonus active: grooming lasts longer and critter output improves.", "마구간 보너스 활성: 털손질이 더 오래가고 크리터 생산량이 향상됩니다." },
            { "Stable occupancy ", "마구간 점유 " },
            { " critters.", " 크리터." },
            { "Stable overcrowded: happiness, grooming, reproduction, and output are reduced.", "마구간 과밀: 행복도, 털손질, 번식, 생산량이 감소합니다." },
            { " overcrowded stables", " 과밀 마구간" },
            { "Overcrowded Stable", "과밀 마구간" },
            { "Bonus: grooming lasts longer; hatches make coal, slicksters make crude oil, dreckos shed plastic, pufts condense slime, and morbs stay calmer. Critters here ", "보너스: 털손질이 더 오래가며 해치는 석탄, 슬릭스터는 원유, 드레코는 플라스틱, 퍼프는 슬라임을 만들고 모브는 더 안정됩니다. 이 방의 크리터 " },
            { "Bonus: grooming lasts longer; hatches make coal, slicksters make crude oil, dreckos shed plastic, pufts condense slime, morbs stay calmer, and pacu produce seafood faster. Critters here ", "보너스: 털손질이 더 오래가며 해치는 석탄, 슬릭스터는 원유, 드레코는 플라스틱, 퍼프는 슬라임을 만들고 모브는 더 안정되며 파쿠는 해산물을 더 빨리 생산합니다. 이 방의 크리터 " },
            { "Bonus: grooming lasts longer; hatches make coal, slicksters make crude oil, dreckos shed plastic, pufts condense slime, morbs stay calmer, pacu produce seafood faster, and shine bugs glow brighter. Critters here ", "보너스: 털손질이 더 오래가며 해치는 석탄, 슬릭스터는 원유, 드레코는 플라스틱, 퍼프는 슬라임을 만들고 모브는 더 안정되고, 파쿠는 해산물을 더 빨리 생산하며 샤인 버그는 더 밝게 빛납니다. 이 방의 크리터 " },
            { "Bonus: grooming lasts longer; hatches make coal, slicksters make crude oil, dreckos shed plastic, pufts condense slime, morbs stay calmer, pacu produce seafood faster, shine bugs glow brighter, and pips plant forest. Critters here ", "보너스: 털손질이 더 오래가며 해치는 석탄, 슬릭스터는 원유, 드레코는 플라스틱, 퍼프는 슬라임을 만들고 모브는 더 안정되고, 파쿠는 해산물을 더 빨리 생산하며 샤인 버그는 더 밝게 빛나고 핍은 숲을 심습니다. 이 방의 크리터 " },
            { "Bonus: grooming lasts longer; hatches make coal, slicksters make crude oil, dreckos shed plastic, pufts condense slime, morbs stay calmer, pacu produce seafood faster, shine bugs glow brighter, pips plant forest, plug slugs charge batteries, gassy moos vent natural gas, and beetas gather radiation samples. Critters here ", "보너스: 털손질이 더 오래가며 해치는 석탄, 슬릭스터는 원유, 드레코는 플라스틱, 퍼프는 슬라임을 만들고 모브는 더 안정되고, 파쿠는 해산물을 더 빨리 생산하며 샤인 버그는 더 밝게 빛나고, 핍은 숲을 심고, 플러그 슬러그는 배터리를 충전하고, 가스 무는 천연가스를 배출하며, 비타는 방사선 샘플을 모읍니다. 이 방의 크리터 " },
            { "Slickster crude output improved.", "슬릭스터 원유 생산이 향상되었습니다." },
            { "Drecko plastic output improved.", "드레코 플라스틱 생산이 향상되었습니다." },
