            { "Trait Mole Hands: dig, build, and deconstruct jobs are 16% faster; morale need +0.2.", "특성 굴착 손: 채굴, 건설, 해체 작업이 16% 빠르며 사기 요구치가 0.2 증가합니다." },
            { "Trait Quick Learner: gains 35% more XP; morale need +0.3.", "특성 빠른 학습: 경험치를 35% 더 얻으며 사기 요구치가 0.3 증가합니다." },
            { "Trait Gearhead: machine, power, repair, refine, and research jobs are 14% faster; morale need +0.2.", "특성 기계광: 기계, 전력, 수리, 제련, 연구 작업이 14% 빠르며 사기 요구치가 0.2 증가합니다." },
            { "Trait Iron Gut: stale food and food poisoning effects are 55% weaker; calorie burn -6%.", "특성 강철 위장: 상한 음식과 식중독 효과가 55% 약하고 칼로리 소모가 6% 낮습니다." },
            { "Trait Diver Lungs: oxygen use and airborne germ intake are 32% lower.", "특성 잠수 폐: 산소 소모와 공기 중 병균 흡입량이 32% 낮습니다." },
            { "Trait Anxious: general work is 8% faster, but morale need and passive stress are higher.", "특성 불안: 일반 작업이 8% 빠르지만 사기 요구치와 지속 스트레스가 높습니다." },
            { "Trait Loud Sleeper: sleeping nearby disrupts other duplicants' rest.", "특성 시끄러운 수면: 가까이서 잠든 다른 복제체의 휴식을 방해합니다." },
            { "Trait Mouth Breather: oxygen use is 55% higher.", "특성 입 호흡: 산소 사용량이 55% 증가합니다." },
            { "Trait Small Bladder: bladder fills 80% faster, increasing toilet pressure.", "특성 작은 방광: 방광이 80% 더 빨리 차 화장실 압박이 커집니다." },
            { "Trait Narcoleptic: may fall asleep at inconvenient moments.", "특성 기면증: 불편한 순간에 잠들 수 있습니다." },
            { "Trait Flatulent: periodically releases natural gas into the room.", "특성 방귀쟁이: 주기적으로 방 안에 천연가스를 방출합니다." },
            { "Trait Gourmet: high quality meals grant extra morale, but poor meals disappoint.", "특성 미식가: 고품질 식사는 추가 사기를 주지만 형편없는 식사는 실망을 줍니다." },
            { "Trait Allergic: floral decor and flowering crops can trigger sneezing, stress, and slower work.", "특성 알레르기: 꽃 장식과 개화 작물이 재채기, 스트레스, 작업 둔화를 유발할 수 있습니다." },
            { "Trait Twinkletoes: moves 20% faster while traveling between errands.", "특성 민첩한 발: 심부름 사이를 이동할 때 20% 더 빠르게 움직입니다." },
            { "Trait Bottomless Stomach: burns 55% more calories and pressures food reserves.", "특성 끝없는 위장: 칼로리를 55% 더 소모해 식량 비축을 압박합니다." },
            { "Trait Nyctophobic: unlit rooms build stress and slow work until lighting improves.", "특성 어둠 공포: 조명이 없는 방에서 스트레스가 쌓이고 조명이 개선될 때까지 작업이 느려집니다." },
            { "Trait Balanced: no special modifier.", "특성 균형: 특별 보정이 없습니다." },
            { "Stress Reaction Vomiter: critical stress creates contaminated spills and germs.", "스트레스 반응 토함: 치명 스트레스가 오염 유출과 병균을 만듭니다." },
            { "Stress Reaction Binge Eater: critical stress consumes stored food for calories and brief relief.", "스트레스 반응 폭식: 치명 스트레스 때 저장 식량을 먹어 칼로리와 짧은 완화를 얻습니다." },
            { "Stress Reaction Destructive: critical stress damages nearby equipment and lasts longer.", "스트레스 반응 파괴: 치명 스트레스 때 주변 설비를 손상시키고 더 오래 지속됩니다." },
            { "Stress Reaction Crier: critical stress spreads stress to nearby duplicants but recovers faster.", "스트레스 반응 울음: 치명 스트레스가 주변 복제체에게 퍼지지만 더 빨리 회복합니다." },
            { "Overjoyed Sparkle Streak: high morale can trigger faster work, movement, and stress relief.", "오버조이 반짝 행진: 높은 사기가 빠른 작업, 이동, 스트레스 완화를 발동할 수 있습니다." },
            { "Overjoyed Super Productive: high morale can trigger faster work, 30% more XP, and 12% more selected output.", "오버조이 초생산성: 높은 사기가 빠른 작업, XP 30% 추가 획득, 일부 산출량 12% 증가를 발동할 수 있습니다." },
            { "Overjoyed Joyful Caretaker: high morale can trigger nearby stress relief.", "오버조이 기쁨 돌봄: 높은 사기가 주변 스트레스 완화를 발동할 수 있습니다." },
            { "Overjoyed Decor Inspired: high morale creates a temporary decor aura that improves nearby morale.", "오버조이 장식 영감: 높은 사기가 주변 사기를 개선하는 임시 장식 오라를 만듭니다." },
