            { "  Research +", "  연구 +" },
            { "Labor: Active ", "노동: 활동 " },
            { " assigned, ", " 배정, " },
            { " open jobs", " 대기 작업" },
            { " blocked jobs", " 막힌 작업" },
            { "Forecast Risk: ", "예측 위험: " },
            { "Build a Medical Cot and rescue the downed duplicant.", "의료 침대를 짓고 쓰러진 복제체를 구조하세요." },
            { "Prioritize rescue errands for downed duplicants.", "쓰러진 복제체 구조 심부름을 우선 처리하세요." },
            { "Cook at the Microbe Musher or harvest mealwood before food runs out.", "식량이 떨어지기 전에 미생물 분쇄기로 조리하거나 밀우드를 수확하세요." },
            { "Cook at the Microbe Musher, crack hatch eggs, or harvest mealwood before food runs out.", "식량이 떨어지기 전에 미생물 분쇄기로 조리하거나 해치 알을 깨거나 밀우드를 수확하세요." },
            { "Cook at the Microbe Musher, crack hatch eggs, grill quality meals, or harvest mealwood before food runs out.", "식량이 떨어지기 전에 미생물 분쇄기로 조리하거나, 해치 알을 깨거나, 고품질 식사를 굽거나, 밀우드를 수확하세요." },
            { "Cook at the Microbe Musher, crack hatch eggs, grill quality meals, or harvest mealwood and bristle berries before food runs out.", "식량이 떨어지기 전에 미생물 분쇄기로 조리하거나, 해치 알을 깨거나, 고품질 식사를 굽거나, 밀우드와 브리슬 베리를 수확하세요." },
            { "Cook at the Microbe Musher, crack hatch eggs, grill quality meals, or harvest mealwood, bristle berries, and dusk caps before food runs out.", "식량이 떨어지기 전에 미생물 분쇄기로 조리하거나, 해치 알을 깨거나, 고품질 식사를 굽거나, 밀우드와 브리슬 베리, 더스크 캡을 수확하세요." },
            { "Cook at the Microbe Musher, crack hatch eggs, grill quality meals, or harvest mealwood, bristle berries, dusk caps, and grubfruit before food runs out.", "식량이 떨어지기 전에 미생물 분쇄기로 조리하거나, 해치 알을 깨거나, 고품질 식사를 굽거나, 밀우드와 브리슬 베리, 더스크 캡, 그럽프루트를 수확하세요." },
            { "Secure food: grow mealwood, cook mush bars, or crack hatch eggs until reserves stabilize.", "식량을 확보하세요: 비축량이 안정될 때까지 밀우드를 키우고, 머시바를 조리하거나 해치 알을 깨세요." },
            { "Harvest mealwood and research Food Preparation for cooked food.", "밀우드를 수확하고 음식 준비를 연구해 조리식을 확보하세요." },
            { "Recycle polluted water and pump clean reserves into storage.", "오염된 물을 재활용하고 깨끗한 물을 저장하세요." },
            { "Pump a water pocket or build a Water Sieve for polluted reserves.", "물웅덩이를 펌프하거나 오염수 처리를 위한 정수기를 지으세요." },
            { "Run diffusers, electrolyzers, or gas vents to restore breathable oxygen.", "산소 발생기, 전해조, 가스 배출구로 숨쉴 산소를 회복하세요." },
            { "Build an Oxygen Diffuser and research Air Systems.", "산소 발생기를 짓고 공기 시스템을 연구하세요." },
            { "Switch oxygen production toward electrolyzers before algae is exhausted.", "조류가 고갈되기 전에 산소 생산을 전해조 중심으로 전환하세요." },
            { "Mine algae and research Air Systems before the diffuser supply fails.", "산소 발생기 공급이 끊기기 전에 조류를 채굴하고 공기 시스템을 연구하세요." },
            { "Build a Carbon Skimmer or vent CO2 away from living spaces.", "탄소 스키머를 짓거나 CO2를 생활 공간 밖으로 배출하세요." },
            { "Research Air Systems so CO2 scrubbing becomes available.", "CO2 정화를 사용할 수 있도록 공기 시스템을 연구하세요." },
            { "Build a Research Station and pick the next colony technology.", "연구소를 짓고 다음 콜로니 기술을 선택하세요." },
            { "Keep the Research Station powered until the focused technology unlocks.", "선택한 기술이 해금될 때까지 연구소에 전력을 유지하세요." },
            { "Generate power and expand battery capacity before machines shut down.", "기계가 멈추기 전에 전력을 생산하고 배터리 용량을 늘리세요." },
            { "Split overloaded circuits with transformers and separate heavy generators.", "변압기로 과부하 회로를 나누고 대형 발전기를 분리하세요." },
            { "Recharge batteries above 35% before the automated grid can prove brownout recovery.", "자동 전력망이 정전 복구를 증명할 수 있도록 먼저 배터리를 35% 이상 충전하세요." },
            { "Link a Smart Battery to a generator before proving automated power recovery.", "자동 전력 복구를 증명하기 전에 스마트 배터리를 발전기에 연결하세요." },
            { "Wire every powered building before proving automated power recovery.", "자동 전력 복구를 증명하기 전에 모든 전력 건물을 배선하세요." },
            { "Hold the automated grid stable until brownout recovery is proven.", "정전 복구가 증명될 때까지 자동 전력망을 안정적으로 유지하세요." },
            { "Build Fire Poles beside the main ladder shaft to shorten vertical commutes.", "수직 통근을 줄이도록 주 사다리 통로 옆에 소방 봉을 지으세요." },
            { "Extend the Fire Pole spine through more floors before transit can be proven.", "이동축을 증명하기 전에 소방 봉 축을 더 많은 층으로 확장하세요." },
            { "Severe long commutes are active; add more vertical access and shorten errands.", "심각한 긴 통근이 발생 중입니다. 수직 접근을 늘리고 심부름 동선을 줄이세요." },
            { "Keep the Fire Pole spine clear until fast vertical transit is proven.", "빠른 수직 이동이 증명될 때까지 소방 봉 축을 막히지 않게 유지하세요." },
            { "Build a Thermo Aquatuner and connect liquid pipes for active cooling.", "능동 냉각을 위해 액체 냉각기를 짓고 액체 배관을 연결하세요." },
            { "Run Liquid Pipe through the Thermo Aquatuner input and output to form a coolant loop.", "냉각수 루프가 되도록 액체 냉각기 입력과 출력에 액체 배관을 연결하세요." },
            { "Feed coolant through the Thermo Aquatuner and keep output pipe capacity free.", "냉각수를 액체 냉각기에 통과시키고 출력 배관 용량을 비워 두세요." },
            { "Use insulated and radiant pipes to move heat until colony temperature stabilizes.", "콜로니 온도가 안정될 때까지 단열/방열 배관으로 열을 이동시키세요." },
            { "Let the Thermo Aquatuner process enough coolant to establish active cooling.", "능동 냉각이 자리 잡도록 액체 냉각기가 충분한 냉각수를 처리하게 두세요." },
            { "Finish active coolant loop stability before enclosing a hot industrial sauna.", "뜨거운 산업 사우나를 밀폐하기 전에 능동 냉각수 루프 안정성을 완료하세요." },
            { "Add insulated tiles around the industrial heat room before trapping steam.", "증기를 가두기 전에 산업 고열 방 주변에 단열 타일을 추가하세요." },
            { "Place a refinery, polymer press, petroleum generator, aquatuner, or sour gas condenser inside the industrial room.", "산업 방 안에 정련기, 폴리머 압착기, 석유 발전기, 액체 냉각기, 또는 사워 가스 응축기를 배치하세요." },
            { "Enclose a hot Machine Room or Power Plant with steam so industrial heat can collect.", "산업 열이 모이도록 뜨거운 기계실이나 발전소를 증기로 밀폐하세요." },
            { "Power and fuel one industrial machine inside the steam room.", "증기 방 안의 산업 기계 하나에 전력과 연료를 공급하세요." },
            { "Wire a Steam Turbine within range of hot steam for industrial heat recovery.", "산업 열 회수를 위해 뜨거운 증기 범위 안에 증기 터빈을 배선하세요." },
            { "Let the Steam Turbine recover more industrial heat before the sauna can be proven.", "사우나를 증명하기 전에 증기 터빈이 산업 열을 더 회수하게 하세요." },
            { "Repair broken equipment before proving industrial sauna stability.", "산업 사우나 안정성을 증명하기 전에 고장난 설비를 수리하세요." },
            { "Stabilize coolant pipes and reservoirs before proving industrial sauna stability.", "산업 사우나 안정성을 증명하기 전에 냉각수 배관과 저장소를 안정화하세요." },
            { "Route duplicants away from scalding industry or through suits before proving sauna safety.", "사우나 안전성을 증명하기 전에 복제체를 고열 산업 구역 밖으로 보내거나 보호복 경로로 보내세요." },
            { "Keep industrial machines, coolant, and Steam Turbines stable until the sauna is proven.", "사우나가 증명될 때까지 산업 기계, 냉각수, 증기 터빈을 안정적으로 유지하세요." },
            { "Food is trending down this cycle; expand farms, cooking, or ranching before reserves slip.", "이번 사이클 식량이 감소 추세입니다. 비축이 흔들리기 전에 농장, 조리, 목축을 확장하세요." },
            { "Clean water is trending down this cycle; pump or recycle water and pause optional consumers.", "이번 사이클 깨끗한 물이 감소 추세입니다. 물을 펌프하거나 재활용하고 선택 소비처를 잠시 멈추세요." },
            { "Breathable oxygen is trending down; increase oxygen production or move gas through vents.", "호흡 가능한 산소가 감소 추세입니다. 산소 생산을 늘리거나 가스 배출구로 대기를 순환시키세요." },
            { "Stored power is trending down; add generation, automation, or battery capacity before the grid browns out.", "저장 전력이 감소 추세입니다. 전력망이 꺼지기 전에 발전, 자동화, 배터리 용량을 추가하세요." },
            { "Food poisoning is active; build a Medical Cot and stabilize sick duplicants.", "식중독이 발생했습니다. 의료 침대를 짓고 아픈 복제체를 안정시키세요." },
            { "Sick duplicants need treatment; build a Medical Cot and produce medicine.", "아픈 복제체에게 치료가 필요합니다. 의료 침대를 짓고 약품을 생산하세요." },
            { "Sick duplicants need treatment; build an Apothecary and compound medicine.", "아픈 복제체에게 치료가 필요합니다. 약제소를 짓고 약품을 조제하세요." },
            { "Sick duplicants need medicine; keep the Apothecary powered with water and algae.", "아픈 복제체에게 약품이 필요합니다. 약제소에 전력, 물, 조류를 공급하세요." },
            { "Food contamination can cause poisoning; grill meals or store food in sterile refrigeration.", "식량 오염이 식중독을 일으킬 수 있습니다. 식사를 굽거나 무균 냉장 보관하세요." },
            { "Food is contaminated; move it to powered refrigeration or sterile chlorine storage.", "식량이 오염되었습니다. 전력 냉장고나 무균 염소 저장고로 옮기세요." },
            { "Food is spoiling without storage; build a Ration Box or powered Refrigerator.", "보관 시설 없이 식량이 상하고 있습니다. 식량 상자나 전력 냉장고를 지으세요." },
            { "Broken equipment is blocking systems; queue repairs before failures cascade.", "고장난 설비가 시스템을 막고 있습니다. 문제가 번지기 전에 수리 작업을 등록하세요." },
            { "Flooding is damaging infrastructure; mop water and protect power wires.", "침수가 기반시설을 손상시키고 있습니다. 물을 닦고 전력 전선을 보호하세요." },
            { "Equipment is overheating; cool rooms or move heat before machines break.", "설비가 과열 중입니다. 기계가 고장나기 전에 방을 식히거나 열을 옮기세요." },
            { "Dangerous pressure pockets can injure duplicants; vent gas or add high-pressure outlets.", "위험 압력 구역이 복제체를 다치게 할 수 있습니다. 가스를 배출하거나 고압 배출구를 추가하세요." },
            { "Meteor shower active; keep bunker doors closed and repair impacts.", "운석우가 진행 중입니다. 벙커 문을 닫아 두고 충돌 피해를 수리하세요." },
            { "Meteor shower active; keep duplicants under cover and build bunker doors after impact.", "운석우가 진행 중입니다. 복제체를 엄폐시키고 충돌 후 벙커 문을 지으세요." },
            { "Meteor warning is near but scanners are blocked; clear sky access above Space Scanners.", "운석 경보 시간이 가까운데 스캐너가 막혀 있습니다. 우주 스캐너 위의 하늘 접근을 비우세요." },
            { "Meteor shower is approaching exposed surface machines; build Bunker Doors for shielding.", "운석우가 노출된 지상 설비에 접근 중입니다. 방어용 벙커 문을 지으세요." },
            { "Link Space Scanner automation to Bunker Doors so the surface seals before impacts.", "충돌 전에 지표면이 봉쇄되도록 우주 스캐너 자동화를 벙커 문에 연결하세요." },
            { "Clear meteor regolith before it blocks solar panels, scanners, or bunker door access.", "운석 레골리스가 태양광 패널, 스캐너, 벙커 문 접근을 막기 전에 치우세요." },
            { "Repair damaged Bunker Doors before the next meteor shower.", "다음 운석우 전에 손상된 벙커 문을 수리하세요." },
            { "Unprotected duplicants are in radiation; pull them back or route them through Lead Suit Checkpoints.", "무보호 복제체가 방사선 안에 있습니다. 뒤로 빼내거나 납 보호복 체크포인트를 통해 이동시키세요." },
            { "Radiation sickness is active; treat duplicants and keep them out of radiation zones.", "방사선병이 발생했습니다. 복제체를 치료하고 방사선 구역 밖에 두세요." },
            { "Research Space Systems before expanding into radiation zones.", "방사선 구역으로 확장하기 전에 우주 시스템을 연구하세요." },
            { "Build Lead Suit Lockers and Checkpoints before routing duplicants through radiation.", "복제체를 방사선 구역으로 보내기 전에 납 보호복 로커와 체크포인트를 지으세요." },
            { "Keep the lead-suit route stable with no unprotected radiation exposure until containment is proven.", "격리가 증명될 때까지 무보호 방사선 노출 없이 납 보호복 경로를 안정적으로 유지하세요." },
            { "Let the colony run long enough to sample food, water, power, and oxygen balance.", "식량, 물, 전력, 산소 균형을 표본으로 볼 수 있을 만큼 콜로니를 운용하세요." },
            { "Stabilize cycle balance: finish a cycle without food, water, power, oxygen, health, or infrastructure losses.", "사이클 균형을 안정화하세요: 식량, 물, 전력, 산소, 건강, 기반시설 손실 없이 한 사이클을 마치세요." },
            { " more cycle(s) to prove long-term sustainability.", "사이클 더 안정적으로 유지해 장기 지속성을 증명하세요." },
            { "Keep the colony stable for ", "콜로니를 " },
            { "Build ladder, floor, or door access to blocked errands.", "막힌 심부름까지 사다리, 바닥, 문 접근로를 만드세요." },
            { "Fix crop atmosphere, water, temperature, or pressure before harvests fail.", "수확이 실패하기 전에 작물의 대기, 물, 온도, 압력을 해결하세요." },
            { "Mop spills before they flood equipment and wires.", "유출액이 설비와 전선을 침수시키기 전에 닦으세요." },
            { "Insulate living areas and add thermal machines to stabilize temperature.", "생활 구역을 단열하고 열 관리 기계를 추가해 온도를 안정화하세요." },
            { "Keep duplicants under cover and repair bunker doors after impacts.", "복제체를 엄폐시키고 충돌 후 벙커 문을 수리하세요." },
            { "Use labor policy and priority controls to reduce the errand backlog.", "노동 정책과 우선순위 제어로 밀린 심부름을 줄이세요." },
            { "No duplicants.", "복제체가 없습니다." },
            { "No duplicant selected.", "선택된 복제체가 없습니다." },
            { "Focused ", "이동 대상 " },
            { " role set to ", " 역할 변경: " },
            { "Printing Pod Ready\nChoose one printable care package. Unpicked offers are recycled when one is claimed.", "프린팅 포드 준비됨\n출력 보급 하나를 선택하세요. 선택하지 않은 보급은 회수됩니다." },
            { "Print ", "출력 " },
            { "READY", "준비됨" },
            { "Duplicant", "복제체" },
            { "Food\n+", "식량\n+" },
            { "Water\n+", "물\n+" },
            { "Algae\n+", "조류\n+" },
