            { "Liquid bridge. Routes liquid west to east and south to north without mixing through the bridge tile.", "액체 브릿지입니다. 브릿지 칸에서 섞지 않고 서쪽에서 동쪽, 남쪽에서 북쪽으로 액체를 넘깁니다." },
            { "Liquid bridge. Routes liquid along the configured direction without mixing through the bridge tile.", "액체 브릿지입니다. 브릿지 칸에서 섞지 않고 설정한 방향으로 액체를 넘깁니다." },
            { "Gas bridge. Routes gas west to east and south to north without mixing through the bridge tile.", "가스 브릿지입니다. 브릿지 칸에서 섞지 않고 서쪽에서 동쪽, 남쪽에서 북쪽으로 기체를 넘깁니다." },
            { "Gas bridge. Routes gas along the configured direction without mixing through the bridge tile.", "가스 브릿지입니다. 브릿지 칸에서 섞지 않고 설정한 방향으로 기체를 넘깁니다." },
            { "Shipping bridge. Routes rail packets west to east and south to north without crossing through the bridge tile.", "운송 브릿지입니다. 브릿지 칸을 가로지르지 않고 서쪽에서 동쪽, 남쪽에서 북쪽으로 레일 화물을 넘깁니다." },
            { "Shipping bridge. Routes rail packets along the configured direction without crossing through the bridge tile.", "운송 브릿지입니다. 브릿지 칸을 가로지르지 않고 설정한 방향으로 레일 화물을 넘깁니다." },
            { "Shipping rail sensor. Sends green when the rail packet matches its filter.", "운송 레일 센서입니다. 레일 화물이 필터와 맞으면 녹색 신호를 보냅니다." },
            { "Shipping rail shutoff. Green automation lets rail packets pass; red blocks the rail.", "운송 레일 차단기입니다. 녹색 자동화 신호는 레일 화물을 통과시키고 적색 신호는 레일을 막습니다." },
            { "Conveyor meter. Limits Shipping Rail packet flow to its configured kg/s rate.", "컨베이어 미터입니다. 운송 레일 화물 흐름을 설정한 kg/초 속도로 제한합니다." },
            { "Automation bridge. Routes automation signals west to east and south to north without crossing through the bridge tile.", "자동화 브릿지입니다. 브릿지 칸을 가로지르지 않고 서쪽에서 동쪽, 남쪽에서 북쪽으로 자동화 신호를 넘깁니다." },
            { "Automation bridge. Routes automation signals along the configured direction without crossing through the bridge tile.", "자동화 브릿지입니다. 브릿지 칸을 가로지르지 않고 설정한 방향으로 자동화 신호를 넘깁니다." },
            { "Automation NOT gate. Inverts automation signals west to east and south to north without crossing through the gate tile.", "자동화 NOT 게이트입니다. 게이트 칸을 가로지르지 않고 서쪽에서 동쪽, 남쪽에서 북쪽으로 자동화 신호를 반전합니다." },
            { "Automation AND gate. Sends green when west and south inputs are both green, with east and north outputs.", "자동화 AND 게이트입니다. 서쪽과 남쪽 입력이 모두 녹색이면 동쪽과 북쪽 출력으로 녹색을 보냅니다." },
            { "Automation OR gate. Sends green when either west or south input is green, with east and north outputs.", "자동화 OR 게이트입니다. 서쪽 또는 남쪽 입력 중 하나라도 녹색이면 동쪽과 북쪽 출력으로 녹색을 보냅니다." },
            { "Automation XOR gate. Sends green when exactly one of west or south inputs is green, with east and north outputs.", "자동화 XOR 게이트입니다. 서쪽과 남쪽 입력 중 정확히 하나만 녹색이면 동쪽과 북쪽 출력으로 녹색을 보냅니다." },
            { "Automation Buffer gate. Sends green while west or south input is green, then holds green for the configured time.", "자동화 버퍼 게이트입니다. 서쪽이나 남쪽 입력이 녹색인 동안 녹색을 보내고, 이후 설정한 시간 동안 녹색을 유지합니다." },
            { "Automation Filter gate. Sends green only after west or south input stays green for the configured time.", "자동화 필터 게이트입니다. 서쪽이나 남쪽 입력이 설정 시간 동안 계속 녹색일 때만 녹색을 보냅니다." },
            { "Automation Memory gate. West set turns output green; south reset turns output red, and reset wins.", "자동화 메모리 게이트입니다. 서쪽 Set은 출력을 녹색으로, 남쪽 Reset은 출력을 적색으로 바꾸며 Reset이 우선합니다." },
            { "Automation Cycle sensor. Sends green during its configured cycle window.", "자동화 사이클 센서입니다. 설정한 사이클 구간 동안 녹색 신호를 보냅니다." },
            { "Automation Timer sensor. Repeats green and red signal durations.", "자동화 타이머 센서입니다. 녹색과 적색 신호 지속 시간을 반복합니다." },
            { "Duplicant motion sensor. Sends green when an active duplicant is nearby.", "복제체 동작 센서입니다. 활동 가능한 복제체가 근처에 있으면 녹색 신호를 보냅니다." },
            { "Germ sensor. Sends green when local germs match the condition.", "병균 센서입니다. 주변 병균이 조건과 맞으면 녹색 신호를 보냅니다." },
            { "Weight plate. Sends green when mass on the tile matches the condition.", "무게판입니다. 칸 위의 무게가 조건과 맞으면 녹색 신호를 보냅니다." },
            { "Gas vent. Releases piped gas until normal room pressure.", "가스 배출구입니다. 방이 일반 압력에 도달할 때까지 배관 가스를 방출합니다." },
