            { "Bonus: excellent rest, morale, and passive stress relief.", "보너스: 수면, 사기, 지속 스트레스 완화가 크게 향상됩니다." },
            { "Bonus: great meals give strong morale and stress relief.", "보너스: 훌륭한 식사가 높은 사기와 스트레스 완화를 제공합니다." },
            { "Bonus: grooming lasts longer and hatches produce more coal. Hatches here ", "보너스: 털손질이 더 오래가고 해치가 석탄을 더 생산합니다. 이 방의 해치 " },
            { "Bonus: machinery produces less heat and wears down slower.", "보너스: 기계가 열을 덜 내고 더 천천히 마모됩니다." },
            { "Bonus: generator tune-ups last longer; machinery produces less heat and wears down slower.", "보너스: 발전기 튠업이 더 오래 지속되고 기계가 열을 덜 내며 더 천천히 마모됩니다." },
