            { "Avoiding Water", "물 회피 중" },
            { "Trapped in Water", "물에 갇힘" },
            { "Waiting for Oxygen Mask", "산소 마스크 대기 중" },
            { "Waiting for Atmo Suit", "대기복 대기 중" },
            { "Dodging Falling Sand", "낙하 모래 회피 중" },
            { "Dodging Meteor Debris", "운석 파편 회피 중" },
            { "Build a Critter Feeder or leave loose dirt, algae, or polluted dirt near hatches.", "크리터 먹이통을 짓거나 해치 근처에 흙, 조류, 오염된 흙 잔해를 두세요." },
            { "Store dirt, algae, or polluted dirt so Critter Feeders can supply hatches.", "크리터 먹이통이 해치에게 공급할 수 있도록 흙, 조류, 오염된 흙을 저장하세요." },
            { "Groom a hatch and let it eat feeder stock or loose debris until it produces coal.", "해치를 돌보고 먹이통 재고나 잔해를 먹게 해 석탄을 생산하게 하세요." },
            { "Explore lower CO2 pockets to discover slicksters for a renewable crude oil loop.", "재생 원유 루프를 위해 하부 CO2 주머니를 탐사해 슬릭스터를 발견하세요." },
            { "Build a Ranching Station near slicksters so duplicants can groom them.", "복제체가 돌볼 수 있도록 슬릭스터 근처에 목축 스테이션을 지으세요." },
            { "Vent CO2 from generators or skimmers near slicksters so they can feed.", "슬릭스터가 먹을 수 있도록 발전기나 탄소 스키머의 CO2를 슬릭스터 근처로 배출하세요." },
            { "Groom a slickster at a Ranching Station to improve crude oil output.", "목축 스테이션에서 슬릭스터를 돌봐 원유 생산량을 높이세요." },
            { "Let a groomed slickster consume CO2 until it produces crude oil.", "돌봄 받은 슬릭스터가 CO2를 소비해 원유를 생산할 때까지 기다리세요." },
            { "Explore upper hydrogen pockets to discover dreckos for renewable plastic.", "재생 플라스틱을 위해 상부 수소 주머니를 탐사해 드레코를 발견하세요." },
            { "Build a Ranching Station near dreckos so duplicants can groom them.", "복제체가 돌볼 수 있도록 드레코 근처에 목축 스테이션을 지으세요." },
            { "Build Planters or a Critter Feeder near dreckos so they have mealwood or algae feed.", "드레코가 밀우드나 조류 먹이를 먹을 수 있도록 드레코 근처에 화분이나 크리터 먹이통을 지으세요." },
            { "Let mealwood grow near dreckos or store algae so nearby feeders can supply them.", "드레코 근처의 밀우드를 키우거나 근처 먹이통이 공급할 수 있도록 조류를 저장하세요." },
            { "Keep dreckos near hydrogen gas so glossy scales can become plastic.", "윤기 나는 비늘이 플라스틱이 되도록 드레코를 수소 가스 근처에 두세요." },
            { "Free dry storage space so drecko plastic can be stored.", "드레코 플라스틱을 저장할 수 있도록 건조 저장 공간을 비우세요." },
            { "Groom a drecko at a Ranching Station to improve plastic scale output.", "목축 스테이션에서 드레코를 돌봐 플라스틱 비늘 생산량을 높이세요." },
            { "Let a groomed drecko eat mealwood or algae in hydrogen until it sheds plastic.", "돌봄 받은 드레코가 수소 안에서 밀우드나 조류를 먹고 플라스틱을 배출할 때까지 기다리세요." },
            { "Explore slime pockets to discover pufts for a polluted oxygen to slime loop.", "오염 산소를 슬라임으로 바꾸는 루프를 위해 슬라임 포켓을 탐사해 퍼프를 발견하세요." },
            { "Build a Ranching Station near pufts so duplicants can groom them.", "복제체가 돌볼 수 있도록 퍼프 근처에 목축 스테이션을 지으세요." },
            { "Dig slime or polluted dirt near pufts so offgas can feed them polluted oxygen.", "오프가스가 퍼프에게 오염 산소 먹이를 공급하도록 퍼프 근처의 슬라임이나 오염된 흙을 파세요." },
            { "Free dry storage space so puft slime can be stored.", "퍼프 슬라임을 저장할 수 있도록 건조 저장 공간을 비우세요." },
            { "Groom a puft at a Ranching Station to improve slime output.", "목축 스테이션에서 퍼프를 돌봐 슬라임 생산량을 높이세요." },
            { "Let a groomed puft consume polluted oxygen until it condenses slime.", "돌봄 받은 퍼프가 오염 산소를 소비해 슬라임을 응축할 때까지 기다리세요." },
            { "Explore slime or polluted dirt pockets to discover morbs before they overwhelm the base.", "기지를 뒤덮기 전에 슬라임이나 오염된 흙 주머니를 탐사해 모브를 발견하세요." },
            { "Keep morbs inside a contained polluted room until they release germy polluted oxygen.", "모브가 병균 섞인 오염 산소를 방출할 때까지 격리된 오염 방 안에 두세요." },
            { "Build Air Deodorizers near morbs to contain their germy polluted oxygen.", "모브 근처에 공기 탈취기를 지어 병균 섞인 오염 산소를 억제하세요." },
            { "Mine dirt or sand so Air Deodorizers can filter morb emissions.", "공기 탈취기가 모브 배출물을 여과할 수 있도록 흙이나 모래를 채굴하세요." },
            { "Let Air Deodorizers filter polluted oxygen released by morbs.", "공기 탈취기가 모브가 방출한 오염 산소를 여과하게 두세요." },
            { "Explore water or salt water pockets to discover pacu for renewable seafood.", "재생 해산물을 위해 물이나 염수 포켓을 탐사해 파쿠를 발견하세요." },
            { "Build a Ranching Station near a water pocket so duplicants can groom pacu.", "복제체가 파쿠를 돌볼 수 있도록 물 포켓 근처에 목축 스테이션을 지으세요." },
            { "Store algae so pacu have feed for aquaculture.", "양식을 위해 파쿠가 먹을 조류를 저장하세요." },
            { "Keep pacu in deep water or salt water so they can keep swimming.", "파쿠가 계속 헤엄칠 수 있도록 깊은 물이나 염수 안에 두세요." },
            { "Groom a pacu at a Ranching Station to improve seafood output.", "목축 스테이션에서 파쿠를 돌봐 해산물 생산량을 높이세요." },
            { "Let a groomed pacu eat algae until it produces fresh seafood.", "돌봄 받은 파쿠가 조류를 먹고 신선한 해산물을 생산할 때까지 기다리세요." },
            { "Explore upper algae pockets to discover shine bugs for living light.", "생체 조명을 위해 상부 조류 주머니를 탐사해 샤인 버그를 발견하세요." },
            { "Build a Ranching Station near shine bugs so duplicants can groom them.", "복제체가 돌볼 수 있도록 샤인 버그 근처에 목축 스테이션을 지으세요." },
            { "Store algae so shine bugs can feed and keep glowing.", "샤인 버그가 먹고 계속 빛날 수 있도록 조류를 저장하세요." },
