            { "beetas need radiation", "비타에게 방사선 필요" },
            { "Bonus: grooming lasts longer; hatches make coal, slicksters make crude oil, molten slicksters make petroleum, dreckos shed plastic, pufts condense slime, morbs stay calmer, pacu produce seafood faster, shine bugs glow brighter, pips plant forest, plug slugs charge batteries, gassy moos vent natural gas, beetas gather radiation samples, grubgrubs tend crops, cuddle pips hatch eggs faster, and shove voles clear regolith. Critters here ", "보너스: 털손질이 더 오래가며 해치는 석탄, 슬릭스터는 원유, 몰튼 슬릭스터는 석유, 드레코는 플라스틱, 퍼프는 슬라임을 만들고 모브는 더 안정되고, 파쿠는 해산물을 더 빨리 생산하며 샤인 버그는 더 밝게 빛나고, 핍은 숲을 심고, 플러그 슬러그는 배터리를 충전하고, 가스 무는 천연가스를 배출하고, 비타는 방사선 샘플을 모으며, 그럽그럽은 작물을 돌보고, 커들 핍은 알 부화를 앞당기고, 쇼브 볼은 레골리스를 정리합니다. 이 방의 크리터 " },
            { "Bonus: grooming lasts longer; hatches make coal, slicksters make crude oil, molten slicksters make petroleum, dreckos shed plastic, pufts condense slime, morbs stay calmer, pacu produce seafood faster, shine bugs glow brighter, pips plant forest, plug slugs charge batteries, gassy moos vent natural gas, beetas gather radiation samples, grubgrubs and sweetles tend crops, cuddle pips hatch eggs faster, and shove voles clear regolith. Critters here ", "보너스: 털손질이 더 오래가며 해치는 석탄, 슬릭스터는 원유, 몰튼 슬릭스터는 석유, 드레코는 플라스틱, 퍼프는 슬라임을 만들고 모브는 더 안정되고, 파쿠는 해산물을 더 빨리 생산하며 샤인 버그는 더 밝게 빛나고, 핍은 숲을 심고, 플러그 슬러그는 배터리를 충전하고, 가스 무는 천연가스를 배출하고, 비타는 방사선 샘플을 모으며, 그럽그럽과 스위틀은 작물을 돌보고, 커들 핍은 알 부화를 앞당기고, 쇼브 볼은 레골리스를 정리합니다. 이 방의 크리터 " },
