            { "Research Space Systems so duplicants can wear Lead Suits near radiation.", "복제체가 방사선 근처에서 납 보호복을 입을 수 있도록 우주 시스템을 연구하세요." },
            { "Build a Lead Suit Locker near a path to space, regolith, or magma radiation.", "우주, 레골리스, 마그마 방사선 경로 근처에 납 보호복 로커를 지으세요." },
            { "Build a Lead Suit Checkpoint beside the locker to control radiation-zone entry.", "방사선 구역 진입을 통제하도록 로커 옆에 납 보호복 체크포인트를 지으세요." },
            { "The Lead Suit Checkpoint is blocking radiation entry; place an adjacent, repaired locker.", "납 보호복 체크포인트가 방사선 구역 진입을 막고 있습니다. 인접한 수리된 로커를 배치하세요." },
            { "Wait for a duplicant to return a Lead Suit or build another locker before sending more workers through.", "추가 복제체를 보내기 전에 납 보호복이 반납되기를 기다리거나 로커를 하나 더 지으세요." },
            { "Send a duplicant through the Lead Suit Checkpoint into a radiating space, regolith, rocket, or magma area.", "복제체를 납 보호복 체크포인트 너머 방사선이 있는 우주, 레골리스, 로켓, 마그마 구역으로 보내세요." },
            { "Keep the Lead Suit route active until radiation protection is proven.", "방사선 보호가 증명될 때까지 납 보호복 경로를 유지하세요." },
            { "Expose a surface, regolith, rocket, or magma radiation zone so containment can be verified.", "격리를 검증할 수 있도록 지표면, 레골리스, 로켓, 마그마 방사선 구역을 노출하세요." },
            { "Run duplicants through Lead Suit Checkpoints until the radiation route cycles suits reliably.", "방사선 경로가 납 보호복을 안정적으로 순환할 때까지 복제체를 납 보호복 체크포인트로 통과시키세요." },
            { "Pull unprotected duplicants out of radiation and route them through Lead Suit Checkpoints.", "무보호 복제체를 방사선 밖으로 빼내고 납 보호복 체크포인트를 통해 이동시키세요." },
            { "Treat radiation sickness and keep sick duplicants out of radiation zones.", "방사선병을 치료하고 아픈 복제체를 방사선 구역 밖에 두세요." },
            { "Maintain a lead-suit radiation route with no unprotected exposure until containment is proven.", "격리가 증명될 때까지 무보호 노출 없이 납 보호복 방사선 경로를 유지하세요." },
            { "Research Space Systems before building a Lead Suit Locker.", "납 보호복 로커를 짓기 전에 우주 시스템을 연구하세요." },
