            { "Build and wire a Research Reactor to turn analyzed radiation samples into nuclear power.", "분석된 방사선 샘플을 핵발전으로 전환할 연구 원자로를 짓고 전선을 연결하세요." },
            { "Build and wire a Radbolt Collector in a radiation zone to focus local radiation into stored charge.", "방사선 구역에 래드볼트 수집기를 짓고 전선을 연결해 국소 방사선을 저장 충전량으로 집중하세요." },
            { "Expose a surface, regolith, magma, rocket, or reactor radiation zone before collecting radbolts.", "래드볼트를 수집하기 전에 표면, 레골리스, 마그마, 로켓, 원자로 방사선 구역을 노출하세요." },
            { "Place, repair, wire, power, or automate a Radbolt Collector where local radiation is strong enough.", "국소 방사선이 충분한 곳에 래드볼트 수집기를 배치하고 수리, 전선, 전력, 자동화를 확인하세요." },
            { "Keep unprotected duplicants away from the Radbolt Collector route.", "보호받지 못한 복제체를 래드볼트 수집기 경로에서 멀리 두세요." },
            { "Treat radiation sickness before certifying radbolt handling.", "래드볼트 취급을 인증하기 전에 방사선병을 치료하세요." },
            { "Let the Radbolt Collector focus radiation until stored charge handling is proven.", "저장 충전량 취급이 입증될 때까지 래드볼트 수집기가 방사선을 집중하게 두세요." },
            { "Prove Radbolt Collector handling before starting post-survey material science.", "조사 이후 소재공학을 시작하기 전에 래드볼트 수집기 취급을 입증하세요." },
            { "Store Radbolt Charge so the Metal Refinery can catalyze thermium material science.", "금속 정제소가 써미움 소재공학을 촉매할 수 있도록 래드볼트 충전량을 저장하세요." },
            { "Build and wire a Metal Refinery to spend Radbolt Charge on material science.", "래드볼트 충전량을 소재공학에 쓸 금속 정제소를 짓고 전선을 연결하세요." },
            { "Repair, enable, and keep the Metal Refinery dry before radbolt material science.", "래드볼트 소재공학 전에 금속 정제소를 수리하고 활성화하며 건조하게 유지하세요." },
            { "Produce extra steel so radbolt-catalyzed thermium testing can run.", "래드볼트 촉매 써미움 시험이 돌아갈 수 있도록 여분의 강철을 생산하세요." },
            { "Launch a post-survey rocket mission to recover niobium for radbolt material science.", "래드볼트 소재공학용 나이오븀을 회수하기 위해 조사 이후 로켓 임무를 발사하세요." },
            { "Store clean water or pipe it beside the Metal Refinery as radbolt material-science coolant.", "래드볼트 소재공학 냉각수로 쓸 깨끗한 물을 저장하거나 금속 정제소 옆으로 배관하세요." },
            { "Free dry storage so radbolt-catalyzed thermium output can be stored.", "래드볼트 촉매 써미움 산출물을 저장할 건조 저장 공간을 비우세요." },
            { "Keep the Metal Refinery powered while it spends Radbolt Charge on thermium material science.", "금속 정제소가 래드볼트 충전량을 써미움 소재공학에 쓰는 동안 전력을 유지하세요." },
            { "Let the Metal Refinery consume Radbolt Charge until material science is proven.", "소재공학이 입증될 때까지 금속 정제소가 래드볼트 충전량을 소비하게 두세요." },
            { "Collect and analyze more radiation samples before starting the reactor.", "원자로를 시작하기 전에 방사선 샘플을 더 수집하고 분석하세요." },
            { "Keep the Orbital Data Bank powered until radiation samples are analyzed for reactor fuel.", "방사선 샘플이 원자로 연료로 분석될 때까지 궤도 데이터 뱅크에 전력을 공급하세요." },
            { "Wire, repair, enable, or automate the Research Reactor so it can fission analyzed samples.", "연구 원자로가 분석된 샘플을 핵분열할 수 있도록 전선 연결, 수리, 활성화, 자동화를 확인하세요." },
            { "Pull unprotected duplicants away from the active reactor or route them through Lead Suit Checkpoints.", "보호받지 못한 복제체를 가동 중인 원자로에서 멀리 보내거나 납 보호복 체크포인트를 통과시키세요." },
            { "Treat radiation sickness before certifying nuclear power.", "핵발전을 인증하기 전에 방사선병을 치료하세요." },
            { "Let the Research Reactor fission analyzed samples until nuclear power is proven.", "핵발전이 입증될 때까지 연구 원자로가 분석된 샘플을 핵분열하게 두세요." },
            { "Run a Radbolt Collector so thermium alloying has stored charge for catalysis.", "써미움 합금에 촉매용 저장 충전량이 생기도록 래드볼트 수집기를 가동하세요." },
            { "Run a Radbolt Collector so super coolant synthesis has stored charge for catalysis.", "초냉매 합성에 촉매용 저장 충전량이 생기도록 래드볼트 수집기를 가동하세요." },
            { "reactor needs samples", "원자로 샘플 부족" },
            { "research reactor idle", "연구 원자로 대기" },
            { "radbolt collector idle", "래드볼트 수집기 대기" },
            { "metal refinery needs radbolt charge", "금속 정제소 래드볼트 충전량 부족" },
            { "Fissions analyzed radiation samples into power, heat, steam, and local radiation.", "분석된 방사선 샘플을 핵분열해 전력, 열, 증기, 국소 방사선을 만듭니다." },
            { "Focuses local radiation into stored radbolt charge for late-game material science.", "국소 방사선을 후반 소재 과학용 래드볼트 저장 충전량으로 집중합니다." },
