            { "Explore the asteroid until a Steam Vent, Salt Water Geyser, Hydrogen Vent, Natural Gas Vent, or Metal Volcano is uncovered.", "증기 분출구, 염수 간헐천, 수소 분출구, 천연가스 분출구, 금속 화산 중 하나가 드러날 때까지 소행성을 탐사하세요." },
            { "Explore the asteroid until a Steam Vent, Salt Water Geyser, Cool Slush Geyser, Hydrogen Vent, Natural Gas Vent, or Metal Volcano is uncovered.", "증기 분출구, 염수 간헐천, 냉슬러시 간헐천, 수소 분출구, 천연가스 분출구, 금속 화산 중 하나가 드러날 때까지 소행성을 탐사하세요." },
            { "Explore the asteroid until a Steam Vent, Salt Water Geyser, Cool Slush Geyser, Chlorine Gas Vent, Hydrogen Vent, Natural Gas Vent, or Metal Volcano is uncovered.", "증기 분출구, 염수 간헐천, 냉슬러시 간헐천, 염소 가스 분출구, 수소 분출구, 천연가스 분출구, 금속 화산 중 하나가 드러날 때까지 소행성을 탐사하세요." },
            { "Explore the asteroid until a Steam Vent, Salt Water Geyser, Cool Slush Geyser, Chlorine Gas Vent, Carbon Dioxide Vent, Hydrogen Vent, Natural Gas Vent, or Metal Volcano is uncovered.", "증기 분출구, 염수 간헐천, 냉슬러시 간헐천, 염소 가스 분출구, 이산화탄소 분출구, 수소 분출구, 천연가스 분출구, 금속 화산 중 하나가 드러날 때까지 소행성을 탐사하세요." },
            { "Explore the asteroid until a Steam Vent, Salt Water Geyser, Cool Slush Geyser, Chlorine Gas Vent, Carbon Dioxide Vent, Polluted Oxygen Vent, Hydrogen Vent, Natural Gas Vent, or Metal Volcano is uncovered.", "증기 분출구, 염수 간헐천, 냉슬러시 간헐천, 염소 가스 분출구, 이산화탄소 분출구, 오염 산소 분출구, 수소 분출구, 천연가스 분출구, 금속 화산 중 하나가 드러날 때까지 소행성을 탐사하세요." },
            { "Explore the asteroid until a Steam Vent, Cool Steam Vent, Leaky Oil Fissure, Salt Water Geyser, Cool Slush Geyser, Chlorine Gas Vent, Carbon Dioxide Vent, Polluted Oxygen Vent, Hydrogen Vent, Natural Gas Vent, or Metal Volcano is uncovered.", "증기 분출구, 냉증기 분출구, 누출 원유 분출구, 염수 간헐천, 냉슬러시 간헐천, 염소 가스 분출구, 이산화탄소 분출구, 오염 산소 분출구, 수소 분출구, 천연가스 분출구, 금속 화산 중 하나가 드러날 때까지 소행성을 탐사하세요." },
            { "Explore the asteroid until a Steam Vent, Water Geyser, Cool Steam Vent, Leaky Oil Fissure, Salt Water Geyser, Cool Slush Geyser, Chlorine Gas Vent, Carbon Dioxide Vent, Polluted Oxygen Vent, Hydrogen Vent, Natural Gas Vent, or Metal Volcano is uncovered.", "증기 분출구, 물 간헐천, 냉증기 분출구, 누출 원유 분출구, 염수 간헐천, 냉슬러시 간헐천, 염소 가스 분출구, 이산화탄소 분출구, 오염 산소 분출구, 수소 분출구, 천연가스 분출구, 금속 화산 중 하나가 드러날 때까지 소행성을 탐사하세요." },
            { "Explore the asteroid until a Steam Vent, Water Geyser, Cool Steam Vent, Leaky Oil Fissure, Salt Water Geyser, Cool Slush Geyser, Polluted Water Vent, Chlorine Gas Vent, Carbon Dioxide Vent, Polluted Oxygen Vent, Hydrogen Vent, Natural Gas Vent, or Metal Volcano is uncovered.", "증기 분출구, 물 간헐천, 냉증기 분출구, 누출 원유 분출구, 염수 간헐천, 냉슬러시 간헐천, 오염수 분출구, 염소 가스 분출구, 이산화탄소 분출구, 오염 산소 분출구, 수소 분출구, 천연가스 분출구, 금속 화산 중 하나가 드러날 때까지 소행성을 탐사하세요." },
            { "Let a natural vent produce renewable water, salt water, hydrogen, or natural gas, then route it through pipes.", "자연 분출구가 재생 가능한 물, 염수, 수소, 천연가스를 생산하게 한 뒤 배관으로 운송하세요." },
            { "Let a natural vent produce renewable water, salt water, polluted water, hydrogen, or natural gas, then route it through pipes.", "자연 분출구가 재생 가능한 물, 염수, 오염수, 수소, 천연가스를 생산하게 한 뒤 배관으로 운송하세요." },
            { "Let a natural vent produce renewable water, salt water, polluted water, chlorine, hydrogen, or natural gas, then route it through pipes.", "자연 분출구가 재생 가능한 물, 염수, 오염수, 염소, 수소, 천연가스를 생산하게 한 뒤 배관으로 운송하세요." },
            { "Let a natural vent produce renewable water, salt water, polluted water, chlorine, carbon dioxide, hydrogen, or natural gas, then route it through pipes.", "자연 분출구가 재생 가능한 물, 염수, 오염수, 염소, 이산화탄소, 수소, 천연가스를 생산하게 한 뒤 배관으로 운송하세요." },
            { "Let a natural vent produce renewable water, salt water, polluted water, chlorine, carbon dioxide, polluted oxygen, hydrogen, or natural gas, then route it through pipes or filters.", "자연 분출구가 재생 가능한 물, 염수, 오염수, 염소, 이산화탄소, 오염 산소, 수소, 천연가스를 생산하게 한 뒤 배관이나 여과기로 처리하세요." },
            { "Let a natural vent produce renewable water, steam, crude oil, salt water, polluted water, chlorine, carbon dioxide, polluted oxygen, hydrogen, or natural gas, then route it through pipes or filters.", "자연 분출구가 재생 가능한 물, 증기, 원유, 염수, 오염수, 염소, 이산화탄소, 오염 산소, 수소, 천연가스를 생산하게 한 뒤 배관이나 여과기로 처리하세요." },
            { "Explore salt biomes until a Salt Water Geyser is uncovered.", "염수 지형을 탐사해 염수 간헐천을 발견하세요." },
            { "Analyze the Salt Water Geyser so the colony can plan its active and dormant cycle.", "식민지가 활성/휴면 주기를 계획할 수 있도록 염수 간헐천을 분석하세요." },
            { "Research Air Systems so the colony can build a Desalinator.", "식민지가 담수화기를 지을 수 있도록 공기 시스템을 연구하세요." },
            { "Build and wire a Desalinator near the Salt Water Geyser output.", "염수 간헐천 출력부 근처에 담수화기를 짓고 전선을 연결하세요." },
            { "Let the analyzed Salt Water Geyser erupt into a pumpable salt water pocket.", "분석된 염수 간헐천이 펌프 가능한 염수 포켓으로 분출하게 두세요." },
            { "Pump or store geyser salt water so the Desalinator can turn it into clean water.", "담수화기가 깨끗한 물로 바꿀 수 있도록 간헐천 염수를 펌프하거나 저장하세요." },
            { "Keep the Desalinator powered until geyser brine becomes clean water and salt.", "간헐천 염수가 깨끗한 물과 소금이 될 때까지 담수화기에 전력을 유지하세요." },
            { "Explore polluted ice biomes until a Cool Slush Geyser is uncovered.", "오염된 얼음 지형을 탐사해 냉슬러시 간헐천을 발견하세요." },
            { "Analyze the Cool Slush Geyser so the colony can plan its cold polluted water cycle.", "식민지가 차가운 오염수 주기를 계획할 수 있도록 냉슬러시 간헐천을 분석하세요." },
            { "Research Air Systems so the colony can sieve cool slush into clean water.", "식민지가 냉슬러시를 깨끗한 물로 여과할 수 있도록 공기 시스템을 연구하세요." },
            { "Build and wire a Water Sieve near the Cool Slush Geyser output.", "냉슬러시 간헐천 출력부 근처에 물 여과기를 짓고 전선을 연결하세요." },
            { "Let the analyzed Cool Slush Geyser erupt into a pumpable polluted water pocket.", "분석된 냉슬러시 간헐천이 펌프 가능한 오염수 포켓으로 분출하게 두세요." },
            { "Pump or store cool slush so the Water Sieve can recycle it into clean water.", "물 여과기가 깨끗한 물로 재활용할 수 있도록 냉슬러시를 펌프하거나 저장하세요." },
            { "Keep the Water Sieve powered and supplied with dirt until cool slush recycling is proven.", "냉슬러시 재활용이 입증될 때까지 물 여과기에 전력과 흙을 공급하세요." },
            { "Explore polluted water biomes until a Polluted Water Vent is uncovered.", "오염수 지형을 탐사해 오염수 분출구를 발견하세요." },
            { "Analyze the Polluted Water Vent so the colony can plan its germy water cycle.", "식민지가 병균 섞인 물 순환을 계획할 수 있도록 오염수 분출구를 분석하세요." },
            { "Research Air Systems so Water Pumps and Water Sieves can tame the Polluted Water Vent.", "물 펌프와 정수기로 오염수 분출구를 제어할 수 있도록 공기 시스템을 연구하세요." },
            { "Build and wire a Water Pump beside the Polluted Water Vent pocket.", "오염수 분출구 포켓 옆에 물 펌프를 짓고 전선을 연결하세요." },
            { "Build a Liquid Reservoir on the Polluted Water Vent line.", "오염수 분출구 배관에 액체 저장소를 지으세요." },
            { "Build and wire a Water Sieve downstream of the Polluted Water Vent reservoir.", "오염수 분출구 저장소 하류에 정수기를 짓고 전선을 연결하세요." },
            { "Let the analyzed Polluted Water Vent erupt into a pumpable germy polluted water pocket.", "분석된 오염수 분출구가 펌프 가능한 병균 섞인 오염수 포켓으로 분출하게 두세요." },
            { "Pump Polluted Water Vent output through liquid pipes toward storage.", "오염수 분출구 출력을 액체 배관으로 저장소까지 펌프하세요." },
            { "Buffer Polluted Water Vent output in a Liquid Reservoir before sieving it.", "거르기 전에 오염수 분출구 출력을 액체 저장소에 완충하세요." },
            { "Keep the Water Sieve powered and supplied with dirt while renewable polluted water stays buffered.", "재생 오염수가 완충되는 동안 정수기에 전력과 흙을 공급하세요." },
            { "Explore caustic biomes until a Chlorine Gas Vent is uncovered.", "부식성 지형을 탐사해 염소 가스 분출구를 발견하세요." },
            { "Analyze the Chlorine Gas Vent so the colony can plan its toxic active cycle.", "식민지가 독성 활성 주기를 계획할 수 있도록 염소 가스 분출구를 분석하세요." },
            { "Research Air Systems so the colony can pump and store chlorine safely.", "식민지가 염소를 안전하게 펌프하고 저장할 수 있도록 공기 시스템을 연구하세요." },
            { "Build and wire a Gas Pump beside the Chlorine Gas Vent pocket.", "염소 가스 분출구 포켓 옆에 가스 펌프를 짓고 전선을 연결하세요." },
            { "Build a Gas Reservoir on the chlorine line to contain renewable chlorine.", "재생 염소를 봉인할 수 있도록 염소 배관에 가스 저장소를 지으세요." },
            { "Let the analyzed Chlorine Gas Vent erupt into a pumpable chlorine pocket.", "분석된 염소 가스 분출구가 펌프 가능한 염소 포켓으로 분출하게 두세요." },
            { "Pump chlorine into a Gas Reservoir until the toxic vent is contained.", "독성 분출구가 봉인될 때까지 염소를 가스 저장소로 펌프하세요." },
            { "Keep the chlorine pump powered while stored chlorine stabilizes sterile storage.", "저장된 염소가 살균 저장 환경을 안정화하는 동안 염소 펌프에 전력을 유지하세요." },
            { "Explore carbon-rich lower biomes until a Carbon Dioxide Vent is uncovered.", "탄소가 풍부한 하부 지형을 탐사해 이산화탄소 분출구를 발견하세요." },
            { "Analyze the Carbon Dioxide Vent so the colony can plan its heavy gas cycle.", "식민지가 무거운 기체 주기를 계획할 수 있도록 이산화탄소 분출구를 분석하세요." },
            { "Research Air Systems so the colony can pump and store carbon dioxide.", "식민지가 이산화탄소를 펌프하고 저장할 수 있도록 공기 시스템을 연구하세요." },
            { "Build and wire a Gas Pump beside the Carbon Dioxide Vent pocket.", "이산화탄소 분출구 포켓 옆에 가스 펌프를 짓고 전선을 연결하세요." },
            { "Build a Gas Reservoir on the carbon dioxide line to buffer renewable CO2.", "재생 이산화탄소를 완충하도록 이산화탄소 배관에 가스 저장소를 지으세요." },
            { "Let the analyzed Carbon Dioxide Vent erupt into a pumpable CO2 pocket.", "분석된 이산화탄소 분출구가 펌프 가능한 CO2 포켓으로 분출하게 두세요." },
            { "Pump CO2 into a Gas Reservoir until the heavy gas source is buffered.", "무거운 기체 공급원이 완충될 때까지 CO2를 가스 저장소로 펌프하세요." },
            { "Keep the CO2 pump powered while stored gas supports sterile storage or slicksters.", "저장된 기체가 살균 저장이나 슬릭스터를 지원하는 동안 CO2 펌프에 전력을 유지하세요." },
            { "Explore slime biomes until a Polluted Oxygen Vent is uncovered.", "슬라임 지형을 탐사해 오염 산소 분출구를 발견하세요." },
            { "Analyze the Polluted Oxygen Vent so the colony can plan its germy active cycle.", "식민지가 병균 섞인 활성 주기를 계획할 수 있도록 오염 산소 분출구를 분석하세요." },
            { "Research Air Systems so the colony can clean polluted oxygen with Air Deodorizers.", "식민지가 공기 탈취기로 오염 산소를 정화할 수 있도록 공기 시스템을 연구하세요." },
            { "Build and wire an Air Deodorizer beside the Polluted Oxygen Vent pocket.", "오염 산소 분출구 포켓 옆에 공기 탈취기를 짓고 전선을 연결하세요." },
            { "Mine dirt or sand so Air Deodorizers can filter the vent's polluted oxygen.", "공기 탈취기가 분출구의 오염 산소를 여과할 수 있도록 흙이나 모래를 채굴하세요." },
            { "Let the analyzed Polluted Oxygen Vent erupt into a deodorizer-cleaned pocket.", "분석된 오염 산소 분출구가 탈취기로 정화되는 포켓에 분출하게 두세요." },
            { "Run Air Deodorizers until enough vented polluted oxygen is cleaned.", "분출된 오염 산소가 충분히 정화될 때까지 공기 탈취기를 가동하세요." },
            { "Keep Air Deodorizers powered while the vent feeds oxygen recovery or pufts.", "분출구가 산소 회수나 퍼프 먹이를 공급하는 동안 공기 탈취기에 전력을 유지하세요." },
            { "Explore hot water biomes until a Steam Vent is uncovered.", "뜨거운 물 지형을 탐사해 증기 분출구를 발견하세요." },
            { "Analyze the Steam Vent so the colony can plan its hot water cycle.", "식민지가 뜨거운 물 주기를 계획할 수 있도록 증기 분출구를 분석하세요." },
            { "Research Air Systems so Water Pumps can pipe Steam Vent output.", "물 펌프가 증기 분출구 출력을 배관으로 보낼 수 있도록 공기 시스템을 연구하세요." },
            { "Build and wire a Water Pump beside the Steam Vent water pocket.", "증기 분출구 물 포켓 옆에 물 펌프를 짓고 전선을 연결하세요." },
            { "Build a Liquid Reservoir on the Steam Vent water line.", "증기 분출구 물 배관에 액체 저장소를 지으세요." },
            { "Let the analyzed Steam Vent condense hot clean water into a pumpable pocket.", "분석된 증기 분출구가 펌프 가능한 포켓에 뜨거운 깨끗한 물을 응축하게 두세요." },
            { "Pump Steam Vent water through liquid pipes toward storage.", "증기 분출구 물을 액체 배관으로 저장소까지 펌프하세요." },
            { "Buffer Steam Vent water in a Liquid Reservoir before using it.", "사용하기 전에 증기 분출구 물을 액체 저장소에 완충하세요." },
            { "Keep the Steam Vent pump controlled and insulated while hot water stays buffered.", "뜨거운 물이 완충되는 동안 증기 분출구 펌프를 제어하고 단열 상태로 유지하세요." },
            { "Explore temperate hot water biomes until a Water Geyser is uncovered.", "온대 온수 지형을 탐사해 물 간헐천을 발견하세요." },
            { "Analyze the Water Geyser so the colony can plan its renewable water cycle.", "식민지가 재생 가능한 물 순환을 계획할 수 있도록 물 간헐천을 분석하세요." },
            { "Research Air Systems so Water Pumps can pipe Water Geyser output.", "물 펌프가 물 간헐천 출력을 배관으로 보낼 수 있도록 공기 시스템을 연구하세요." },
            { "Build and wire a Water Pump beside the Water Geyser pocket.", "물 간헐천 포켓 옆에 물 펌프를 짓고 전선을 연결하세요." },
            { "Build a Liquid Reservoir on the Water Geyser line.", "물 간헐천 배관에 액체 저장소를 지으세요." },
            { "Let the analyzed Water Geyser erupt into a pumpable hot water pocket.", "분석된 물 간헐천이 펌프 가능한 뜨거운 물 포켓으로 분출하게 두세요." },
            { "Pump Water Geyser output through liquid pipes toward storage.", "물 간헐천 출력을 액체 배관으로 저장소까지 펌프하세요." },
            { "Buffer Water Geyser output in a Liquid Reservoir before using it.", "사용하기 전에 물 간헐천 출력을 액체 저장소에 완충하세요." },
            { "Keep the Water Geyser pump controlled while renewable water stays buffered.", "재생 물이 완충되는 동안 물 간헐천 펌프를 제어 상태로 유지하세요." },
            { "Explore hot water biomes until a Cool Steam Vent is uncovered.", "뜨거운 물 지형을 탐사해 냉증기 분출구를 발견하세요." },
            { "Analyze the Cool Steam Vent so the colony can forecast its steam cycle.", "식민지가 증기 주기를 예측할 수 있도록 냉증기 분출구를 분석하세요." },
            { "Research Advanced Power so Steam Turbines can harvest the Cool Steam Vent.", "증기 터빈이 냉증기 분출구를 회수할 수 있도록 고급 전력을 연구하세요." },
            { "Build and wire a Steam Turbine above the Cool Steam Vent chamber.", "냉증기 분출구 챔버 위에 증기 터빈을 짓고 전선을 연결하세요." },
            { "Let the analyzed Cool Steam Vent fill an insulated chamber with hot steam.", "분석된 냉증기 분출구가 단열 챔버를 뜨거운 증기로 채우게 두세요." },
            { "Run a Steam Turbine close to the Cool Steam Vent until generated steam is harvested.", "생성된 증기가 회수될 때까지 냉증기 분출구 가까이의 증기 터빈을 가동하세요." },
            { "Keep the Cool Steam Vent chamber sealed while the Steam Turbine recovers water and power.", "증기 터빈이 물과 전력을 회수하는 동안 냉증기 분출구 챔버를 밀폐하세요." },
            { "Explore upper caustic biomes until a Hydrogen Vent is uncovered.", "상층 부식성 지형을 탐사해 수소 분출구를 발견하세요." },
            { "Analyze the Hydrogen Vent so the colony can plan its hot hydrogen cycle.", "식민지가 뜨거운 수소 주기를 계획할 수 있도록 수소 분출구를 분석하세요." },
            { "Research Advanced Power so Hydrogen Generators can burn vent hydrogen.", "수소 발전기가 분출구 수소를 태울 수 있도록 고급 전력을 연구하세요." },
            { "Build and wire a Gas Pump beside the Hydrogen Vent pocket.", "수소 분출구 포켓 옆에 가스 펌프를 짓고 전선을 연결하세요." },
            { "Build a Gas Reservoir on the hydrogen line to buffer renewable fuel.", "재생 연료를 완충하도록 수소 배관에 가스 저장소를 지으세요." },
            { "Build and wire a Hydrogen Generator fed by the hydrogen line.", "수소 배관에서 공급받는 수소 발전기를 짓고 전선을 연결하세요." },
            { "Let the analyzed Hydrogen Vent erupt into a pumpable hydrogen pocket.", "분석된 수소 분출구가 펌프 가능한 수소 포켓으로 분출하게 두세요." },
            { "Pump hydrogen into a Gas Reservoir until the light gas source is buffered.", "가벼운 기체 공급원이 완충될 때까지 수소를 가스 저장소로 펌프하세요." },
            { "Run a Hydrogen Generator until vent hydrogen becomes renewable power.", "분출구 수소가 재생 전력이 될 때까지 수소 발전기를 가동하세요." },
            { "Keep the hydrogen pump and generator controlled while renewable power stays online.", "재생 전력이 유지되는 동안 수소 펌프와 발전기를 제어 상태로 유지하세요." },
            { "Explore lower caustic biomes until a Natural Gas Vent is uncovered.", "하층 부식성 지형을 탐사해 천연가스 분출구를 발견하세요." },
            { "Analyze the Natural Gas Vent so the colony can plan its hot fuel cycle.", "식민지가 뜨거운 연료 주기를 계획할 수 있도록 천연가스 분출구를 분석하세요." },
            { "Research Advanced Power so Natural Gas Generators can burn vent fuel.", "천연가스 발전기가 분출구 연료를 태울 수 있도록 고급 전력을 연구하세요." },
            { "Build and wire a Gas Pump beside the Natural Gas Vent pocket.", "천연가스 분출구 포켓 옆에 가스 펌프를 짓고 전선을 연결하세요." },
            { "Build a Gas Reservoir on the natural gas line to buffer renewable fuel.", "재생 연료를 완충하도록 천연가스 배관에 가스 저장소를 지으세요." },
            { "Build and wire a Natural Gas Generator fed by the vent gas line.", "분출구 가스 배관에서 공급받는 천연가스 발전기를 짓고 전선을 연결하세요." },
            { "Let the analyzed Natural Gas Vent erupt into a pumpable fuel pocket.", "분석된 천연가스 분출구가 펌프 가능한 연료 포켓으로 분출하게 두세요." },
            { "Pump natural gas into a Gas Reservoir until the fuel source is buffered.", "연료 공급원이 완충될 때까지 천연가스를 가스 저장소로 펌프하세요." },
            { "Run a Natural Gas Generator until vent fuel becomes renewable power.", "분출구 연료가 재생 전력이 될 때까지 천연가스 발전기를 가동하세요." },
            { "Keep the natural gas pump and generator controlled while renewable fuel stays online.", "재생 연료가 유지되는 동안 천연가스 펌프와 발전기를 제어 상태로 유지하세요." },
            { "Explore the lower oil biome until a Leaky Oil Fissure is uncovered.", "하층 원유 지형을 탐사해 누출 원유 분출구를 발견하세요." },
            { "Analyze the Leaky Oil Fissure so the colony can plan its crude oil cycle.", "식민지가 원유 주기를 계획할 수 있도록 누출 원유 분출구를 분석하세요." },
            { "Research Advanced Power so the colony can refine fissure crude oil.", "식민지가 분출구 원유를 정제할 수 있도록 고급 전력을 연구하세요." },
            { "Build and wire an Oil Refinery near stored crude from the Leaky Oil Fissure.", "누출 원유 분출구에서 저장한 원유 근처에 정유기를 짓고 전선을 연결하세요." },
            { "Let the analyzed Leaky Oil Fissure drip crude oil into a pumpable pocket.", "분석된 누출 원유 분출구가 펌프 가능한 포켓에 원유를 떨어뜨리게 두세요." },
            { "Pump fissure crude into storage and run an Oil Refinery until petroleum is produced.", "분출구 원유를 저장고로 펌프하고 석유가 생산될 때까지 정유기를 가동하세요." },
            { "Keep the Leaky Oil Fissure contained while petroleum production stays online.", "석유 생산이 유지되는 동안 누출 원유 분출구를 봉인 상태로 관리하세요." },
            { "Renewable natural geyser. Emits warm salt water into an adjacent pocket while active.", "재생 가능한 자연 간헐천입니다. 활성 상태일 때 인접한 공간에 따뜻한 염수를 분출합니다." },
            { "Renewable natural geyser. Emits cold polluted water into an adjacent pocket while active.", "재생 가능한 자연 간헐천입니다. 활성 상태일 때 인접한 공간에 차가운 오염수를 분출합니다." },
            { "Renewable natural vent. Emits warm germy polluted water into an adjacent pocket while active.", "재생 가능한 자연 분출구입니다. 활성 상태일 때 인접한 공간에 따뜻하고 병균 섞인 오염수를 분출합니다." },
            { "Renewable natural vent. Emits warm chlorine gas into nearby gas when active.", "재생 가능한 자연 분출구입니다. 활성 상태일 때 주변 기체 공간에 따뜻한 염소 가스를 분출합니다." },
            { "Renewable natural vent. Emits warm carbon dioxide into nearby gas when active.", "재생 가능한 자연 분출구입니다. 활성 상태일 때 주변 기체 공간에 따뜻한 이산화탄소를 분출합니다." },
            { "Renewable natural vent. Emits germy polluted oxygen into nearby gas when active.", "재생 가능한 자연 분출구입니다. 활성 상태일 때 주변 기체 공간에 병균 섞인 오염 산소를 분출합니다." },
            { "Renewable natural vent. Emits hot steam into nearby gas when active.", "재생 가능한 자연 분출구입니다. 활성 상태일 때 주변 기체 공간에 뜨거운 증기를 분출합니다." },
            { "Renewable natural geyser. Emits hot clean water into an adjacent pocket while active.", "재생 가능한 자연 간헐천입니다. 활성 상태일 때 인접한 공간에 뜨거운 깨끗한 물을 분출합니다." },
            { "Renewable natural vent. Emits hot hydrogen into nearby gas when active.", "재생 가능한 자연 분출구입니다. 활성 상태일 때 주변 기체 공간에 뜨거운 수소를 분출합니다." },
            { "Renewable natural vent. Emits hot natural gas into nearby gas when active.", "재생 가능한 자연 분출구입니다. 활성 상태일 때 주변 기체 공간에 뜨거운 천연가스를 분출합니다." },
            { "Renewable natural vent. Drips hot crude oil into an adjacent pocket while active.", "재생 가능한 자연 분출구입니다. 활성 상태일 때 인접한 공간에 뜨거운 원유를 흘립니다." },
