        private static readonly string[] KoreanKeys = Korean.Keys
            .OrderByDescending(key => key.Length)
            .ToArray();

        private static readonly Dictionary<char, string[]> KoreanKeysByFirstCharacter = KoreanKeys
            .GroupBy(key => key[0])
            .ToDictionary(group => group.Key, group => group.ToArray());

        private static readonly Dictionary<string, string> KoreanBlockCache = new Dictionary<string, string>();

        public static string LocalizeBlock(string text, ProjectONLanguage language)
        {
            if (language == ProjectONLanguage.English || string.IsNullOrEmpty(text))
            {
                return text;
            }

            if (Korean.TryGetValue(text, out string exactLocalized))
            {
                return exactLocalized;
            }

            if (KoreanBlockCache.TryGetValue(text, out string cachedLocalized))
            {
                return cachedLocalized;
            }

            StringBuilder builder = null;
            int copiedUntil = 0;
            int index = 0;
            while (index < text.Length)
            {
                if (!KoreanKeysByFirstCharacter.TryGetValue(text[index], out string[] candidates))
                {
                    index++;
                    continue;
                }

                string matchedKey = null;
                foreach (string key in candidates)
                {
                    if (key.Length <= text.Length - index &&
                        string.CompareOrdinal(text, index, key, 0, key.Length) == 0)
                    {
                        matchedKey = key;
                        break;
                    }
                }

                if (matchedKey == null)
                {
                    index++;
                    continue;
                }

                if (builder == null)
                {
                    builder = new StringBuilder(text.Length);
                }

                if (index > copiedUntil)
                {
                    builder.Append(text, copiedUntil, index - copiedUntil);
                }

                builder.Append(Korean[matchedKey]);
                index += matchedKey.Length;
                copiedUntil = index;
            }

            if (builder == null)
            {
                RememberKoreanBlock(text, text);
                return text;
            }

            if (copiedUntil < text.Length)
            {
                builder.Append(text, copiedUntil, text.Length - copiedUntil);
            }

            string localized = builder.ToString();
            RememberKoreanBlock(text, localized);
            return localized;
        }

        private static void RememberKoreanBlock(string text, string localized)
        {
            if (KoreanBlockCache.Count >= MaxKoreanBlockCacheEntries)
            {
                KoreanBlockCache.Clear();
            }

            KoreanBlockCache[text] = localized;
        }
    }
